; =============================================================================
; runtime.asm — routines embedded in every executable generated by nihilc.
;
; Assembled with `nasm -f bin` and included in the compiler with incbin. It is copied
; byte by byte to offset SIZE_HEADER of the executable, which is the entry
; point; that is why `org` is the final virtual address.
;
; Convention: routines may destroy rax, rcx, rdx, rsi, rdi, r8–r11 and
; preservam rbx, rbp, rsp, r12–r15.
; =============================================================================

bits 64
default abs                         ; data at a fixed absolute address
%include "layout.inc"
org BASE_CODE + SIZE_HEADER

start:
    db 0xE9
    dd 0                            ; jmp program — patched by nihilc

; ---- jump table (fixed offsets, see layout.inc) -----------------------
t_div:          jmp strict near rt_div             ; RT_DIV
t_mod:          jmp strict near rt_mod             ; RT_MOD
t_print_int:  jmp strict near rt_print_int     ; RT_IMPRIME_INT
t_print_bool: jmp strict near rt_print_bool    ; RT_IMPRIME_BOOL
t_print_str:  jmp strict near rt_print_str     ; RT_IMPRIME_STR
t_exit:         jmp strict near rt_exit            ; RT_SAIR
t_error:         jmp strict near rt_error            ; RT_ERRO
t_alloc:        jmp strict near rt_alloc           ; RT_ALOCA
t_array_rep:    jmp strict near rt_array_rep       ; RT_ARRAY_REP
t_error_index:  jmp strict near rt_error_index     ; RT_ERRO_INDICE
t_write_byte: jmp strict near rt_write_byte    ; RT_ESCREVE_BYTE
t_read_byte:      jmp strict near rt_read_byte         ; RT_LE_BYTE
t_str_equal:    jmp strict near rt_str_equal       ; RT_STR_IGUAL
t_error_int:     jmp strict near rt_error_int        ; RT_ERRO_INT
t_error_bool:    jmp strict near rt_error_bool       ; RT_ERRO_BOOL
t_error_str:     jmp strict near rt_error_str        ; RT_ERRO_STR
t_read_file:   jmp strict near rt_read_file      ; RT_LE_ARQUIVO
t_text:        jmp strict near rt_text           ; RT_TEXTO
t_print_int_opt:  jmp strict near rt_print_int_opt ; RT_IMPRIME_INT_OPC
t_print_bool_opt: jmp strict near rt_print_bool_opt ; RT_IMPRIME_BOOL_OPC
t_print_str_opt:  jmp strict near rt_print_str_opt ; RT_IMPRIME_STR_OPC
t_err_int_opt:  jmp strict near rt_error_int_opt    ; RT_ERRO_INT_OPC
t_err_bool_opt: jmp strict near rt_error_bool_opt   ; RT_ERRO_BOOL_OPC
t_err_str_opt:  jmp strict near rt_error_str_opt    ; RT_ERRO_STR_OPC
t_read_file_opt:   jmp strict near rt_read_file_opt  ; RT_LE_ARQUIVO_OPC
t_concat:       jmp strict near rt_concat          ; RT_CONCAT
t_sleep:        jmp strict near rt_sleep           ; RT_SLEEP
t_write_file:   jmp strict near rt_write_file      ; RT_WRITE_FILE
t_append_file:  jmp strict near rt_append_file     ; RT_APPEND_FILE
t_read_at:      jmp strict near rt_read_at         ; RT_READ_AT
t_write_at:     jmp strict near rt_write_at        ; RT_WRITE_AT
t_write_at_ns:  jmp strict near rt_write_at_ns     ; RT_WRITE_AT_NS
t_truncate:     jmp strict near rt_truncate        ; RT_TRUNCATE
t_truncate_ns:  jmp strict near rt_truncate_ns     ; RT_TRUNCATE_NS
t_int_text:     jmp strict near rt_int_text        ; RT_INT_TEXT
t_array_concat: jmp strict near rt_array_concat    ; RT_ARRAY_CONCAT
t_net_listen:   jmp strict near rt_net_listen      ; RT_NET_LISTEN
t_net_accept:   jmp strict near rt_net_accept      ; RT_NET_ACCEPT
t_fd_read:      jmp strict near rt_fd_read         ; RT_FD_READ
t_fd_send:      jmp strict near rt_fd_send         ; RT_FD_SEND
t_fd_close:     jmp strict near rt_fd_close        ; RT_FD_CLOSE
t_syscall:      jmp strict near rt_syscall         ; RT_SYSCALL
t_json_end:     jmp strict near rt_json_end        ; RT_JSON_END
t_sub:          jmp strict near rt_sub             ; RT_SUB
t_put:          jmp strict near rt_put             ; RT_PUT
t_rec_parse:    jmp strict near rt_rec_parse       ; RT_REC_PARSE
t_lines:        jmp strict near rt_lines           ; RT_LINES
t_net_connect:  jmp strict near rt_net_connect     ; RT_NET_CONNECT
t_protect:      jmp strict near rt_protect         ; RT_PROTECT
t_unprotect:    jmp strict near rt_unprotect       ; RT_UNPROTECT
t_err_text:     jmp strict near rt_err_text        ; RT_ERR_TEXT
t_fail:         jmp strict near rt_fail            ; RT_FAIL

; ---- arithmetic -------------------------------------------------------------
; Division truncated toward zero (as in C). MIN / -1 gives MIN (idiv
; would raise SIGFPE) and MIN % -1 gives 0.
rt_div:
    test rcx, rcx
    jz error_div_zero
    cmp rcx, -1
    je .minus_one
    cqo
    idiv rcx
    ret
.minus_one:
    neg rax
    ret

rt_mod:
    test rcx, rcx
    jz error_div_zero
    cmp rcx, -1
    je .zero
    cqo
    idiv rcx
    mov rax, rdx
    ret
.zero:
    xor eax, eax
    ret

error_div_zero:
    lea rsi, [rel s_div_zero]
    jmp rt_error

; ---- output ------------------------------------------------------------------
rt_print_int:
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    call rt_buffer
    add rsp, 32
    ret

; rt_decimal: rax = signed value, rdi = end of a buffer (≥ 20 bytes before it)
; → rsi = start of the digits. Destroys rax, rcx, rdx, r8.
rt_decimal:
    mov r8, rax
    test rax, rax
    jns .positive
    neg rax                         ; MIN stays MIN, but the unsigned div gets it right
.positive:
    mov ecx, 10
.digit:
    xor edx, edx
    div rcx
    add dl, '0'
    dec rdi
    mov [rdi], dl
    test rax, rax
    jnz .digit
    test r8, r8
    jns .finish
    dec rdi
    mov byte [rdi], '-'
.finish:
    mov rsi, rdi
    ret

; ---- network (stage 1, SPEC §23): a TCP server -----------------------------------
; rt_net_listen: rax = port, rcx = 1 to accept on every address (0: only 127.0.0.1)
;   → rax = the listening socket, or -errno
rt_net_listen:
    push rbx
    push r12
    sub rsp, 32
    mov r12, rax                    ; port
    mov rbx, rcx                    ; every address?
    mov eax, 41                     ; socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0)
    mov edi, 2
    mov esi, 1 | 0x80000
    xor edx, edx
    syscall
    test rax, rax
    js .end
    mov [rsp + 24], rax             ; the socket
    mov dword [rsp + 16], 1
    mov eax, 54                     ; setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &1, 4)
    mov rdi, [rsp + 24]
    mov esi, 1
    mov edx, 2
    lea r10, [rsp + 16]
    mov r8d, 4
    syscall
    mov word [rsp], 2               ; sockaddr_in: AF_INET,
    mov eax, r12d
    xchg al, ah                     ; the port in network order,
    mov [rsp + 2], ax
    mov dword [rsp + 4], 0x0100007F ; 127.0.0.1 …
    test rbx, rbx
    jz .bind
    mov dword [rsp + 4], 0          ; … or every address
.bind:
    mov qword [rsp + 8], 0
    mov eax, 49                     ; bind(fd, &addr, 16)
    mov rdi, [rsp + 24]
    mov rsi, rsp
    mov edx, 16
    syscall
    test rax, rax
    js .fail
    mov eax, 50                     ; listen(fd, 128)
    mov rdi, [rsp + 24]
    mov esi, 128
    syscall
    test rax, rax
    js .fail
    mov rax, [rsp + 24]
    jmp .end
.fail:
    push rax
    mov eax, 3                      ; close the socket
    mov rdi, [rsp + 32]
    syscall
    pop rax
.end:
    add rsp, 32
    pop r12
    pop rbx
    ret

; rt_net_connect: rax = IPv4 address (a << 24 | b << 16 | c << 8 | d), rcx = port
;   → rax = a socket connected to it, or -errno (SPEC §23: the client side)
rt_net_connect:
    push rbx
    push r12
    sub rsp, 24
    mov r12, rax                    ; address
    mov rbx, rcx                    ; port
    mov eax, 41                     ; socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0)
    mov edi, 2
    mov esi, 1 | 0x80000
    xor edx, edx
    syscall
    test rax, rax
    js .end
    mov [rsp + 16], rax             ; the socket
    mov word [rsp], 2               ; sockaddr_in: AF_INET,
    mov eax, ebx
    xchg al, ah                     ; the port in network order,
    mov [rsp + 2], ax
    mov eax, r12d
    bswap eax                       ; the address in network order
    mov [rsp + 4], eax
    mov qword [rsp + 8], 0
.again:
    mov eax, 42                     ; connect(fd, &addr, 16)
    mov rdi, [rsp + 16]
    mov rsi, rsp
    mov edx, 16
    syscall
    cmp rax, -4                     ; -EINTR: again
    je .again
    test rax, rax
    js .fail
    mov rax, [rsp + 16]
    jmp .end
.fail:
    push rax
    mov eax, 3                      ; close the socket
    mov rdi, [rsp + 24]
    syscall
    pop rax
.end:
    add rsp, 24
    pop r12
    pop rbx
    ret

; rt_net_accept: rax = listening socket → rax = the connection, or -errno. The pending
; output is written first, so what the program printed shows up while it waits.
rt_net_accept:
    push rbx
    mov rbx, rax
    call rt_flush
.again:
    mov eax, 288                    ; accept4(fd, NULL, NULL, SOCK_CLOEXEC)
    mov rdi, rbx
    xor esi, esi
    xor edx, edx
    mov r10d, 0x80000
    syscall
    cmp rax, -4                     ; -EINTR: again
    je .again
    test rax, rax
    js .done
    push rax                        ; a connection that sends nothing must not hold the server
    sub rsp, 16                     ; (it serves one at a time): reads give up after 15 s
    mov qword [rsp], 15             ; struct timeval: seconds,
    mov qword [rsp + 8], 0          ; microseconds
    mov rdi, rax
    mov eax, 54                     ; setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, 16)
    mov esi, 1
    mov edx, 20
    mov r10, rsp
    mov r8d, 16
    syscall
    add rsp, 16
    pop rax
.done:
    pop rbx
    ret

; rt_fd_read: rax = fd, rcx = most bytes → rax = a new STRING with what one read gave
; (length 0 at the end, or on an error)
rt_fd_read:
    push rbx
    push r12
    push r13
    mov r12, rax
    mov r13, rcx
    test r13, r13
    jg .size
    mov r13d, 65536
.size:
    lea rcx, [r13 + 8]
    shr rcx, 3
    call rt_alloc
    mov rbx, rax
.read:
    xor eax, eax                    ; read(fd, buffer, most)
    mov rdi, r12
    mov rsi, rbx
    mov rdx, r13
    syscall
    cmp rax, -4
    je .read
    test rax, rax
    jns .got
    xor eax, eax
.got:
    mov [rbx - 8], rax              ; the length (the block keeps its size)
    mov byte [rbx + rax], 0
    mov rax, rbx
    pop r13
    pop r12
    pop rbx
    ret

; rt_fd_send: rax = fd (a socket), rcx = text → sends all of it; rax = 0, or -errno.
; MSG_NOSIGNAL: a client that went away is an error, not the end of the program (SIGPIPE).
rt_fd_send:
    push rbx
    push r12
    push r13
    mov r12, rax
    mov rbx, rcx
    mov r13, [rcx - 8]
.loop:
    test r13, r13
    jz .done
    mov eax, 44                     ; sendto(fd, text, n, MSG_NOSIGNAL, NULL, 0)
    mov rdi, r12
    mov rsi, rbx
    mov rdx, r13
    mov r10d, 0x4000
    xor r8d, r8d
    xor r9d, r9d
    syscall
    cmp rax, -4
    je .loop
    test rax, rax
    js .end
    add rbx, rax
    sub r13, rax
    jmp .loop
.done:
    xor eax, eax
.end:
    pop r13
    pop r12
    pop rbx
    ret

; rt_fd_close: rax = fd
rt_fd_close:
    mov rdi, rax
    mov eax, 3
    syscall
    ret

; rt_json_end: rax = STRING s, rcx = i → rax = the position after the JSON value that starts
; at i (after spaces), or -1 if there is no valid value there. The inner loop of the JSON
; library (SPEC §21.2), the same rule as the prelude had: a string ends at its closing quote
; (a backslash skips the next byte); an object or array where its brackets balance (strings
; inside skipped); anything else (number, true, false, null) at , } ] or a space.
rt_json_end:
    push rbx
    mov rsi, rax                    ; the bytes
    mov rdx, [rax - 8]              ; n
    mov rbx, rcx                    ; i
    test rbx, rbx
    js .fail
.ws:
    cmp rbx, rdx
    jae .fail
    movzx eax, byte [rsi + rbx]
    cmp al, 32
    je .ws_next
    cmp al, 10
    je .ws_next
    cmp al, 13
    je .ws_next
    cmp al, 9
    jne .value
.ws_next:
    inc rbx
    jmp .ws
.value:
    cmp al, '"'
    je .string
    cmp al, '{'
    je .nest
    cmp al, '['
    je .nest
    mov rcx, rbx                    ; a number, true, false or null
.scalar:
    cmp rbx, rdx
    jae .scalar_end
    movzx eax, byte [rsi + rbx]
    cmp al, ','
    je .scalar_end
    cmp al, '}'
    je .scalar_end
    cmp al, ']'
    je .scalar_end
    cmp al, 32
    je .scalar_end
    cmp al, 10
    je .scalar_end
    cmp al, 13
    je .scalar_end
    cmp al, 9
    je .scalar_end
    inc rbx
    jmp .scalar
.scalar_end:
    cmp rbx, rcx
    je .fail
    mov rax, rbx
    jmp .end
.string:
    call json_skip_string
    test rbx, rbx
    js .fail
    mov rax, rbx
    jmp .end
.nest:
    xor ecx, ecx                    ; depth
.nest_loop:
    cmp rbx, rdx
    jae .fail
    movzx eax, byte [rsi + rbx]
    cmp al, '"'
    jne .bracket
    call json_skip_string
    test rbx, rbx
    js .fail
    jmp .nest_loop
.bracket:
    inc rbx
    cmp al, '{'
    je .open
    cmp al, '['
    je .open
    cmp al, '}'
    je .close
    cmp al, ']'
    jne .nest_loop
.close:
    dec rcx
    jnz .nest_loop
    mov rax, rbx
    jmp .end
.open:
    inc rcx
    jmp .nest_loop
.fail:
    mov rax, -1
.end:
    pop rbx
    ret

; rt_sub: rax = STRING s, rcx = a, rdx = b → rax = a new STRING with the bytes a … b - 1
; (the prelude's __nihil_sub: slices, split, JSON parts, text fields of tables)
rt_sub:
    push rbx
    push r12
    push r13
    mov rbx, rax
    mov r12, rcx
    mov r13, rdx
    sub r13, r12                    ; n
    jns .size
    xor r13d, r13d
.size:
    lea rcx, [r13 + 8]              ; n + 1 bytes, zeroed: the 0 at the end comes with it
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13
    mov rdi, rax
    lea rsi, [rbx + r12]
    mov rcx, r13
    rep movsb
    pop r13
    pop r12
    pop rbx
    ret

; rt_put: rax = STRING r (a new one the prelude is building), rcx = at, rdx = STRING t →
; the bytes of t copied into r from position at; rax = at + #t
rt_put:
    lea rdi, [rax + rcx]
    mov rsi, rdx
    mov r8, rcx
    mov rcx, [rdx - 8]
    add r8, rcx
    rep movsb
    mov rax, r8
    ret

; rt_lines: rax = text, rcx = width → rax = the number of lines when every line has exactly
; that width (the last one may lack its "\n"); -1 if one does not (the prelude then finds it
; and says which). NAME @ path checks this before reading the records.
rt_lines:
    push rbx
    push r11
    mov rsi, rax
    mov rdx, [rax - 8]              ; n bytes
    mov r8, rcx                     ; width
    test r8, r8
    jle .bad
    test rdx, rdx
    jz .none
    lea r9, [r8 + 1]
    mov rax, rdx
    xor edx, edx
    div r9                          ; rax = whole lines (with "\n"), rdx = what is left
    mov rcx, rax                    ; lines
    mov r10, rax                    ; line breaks there must be
    test rdx, rdx
    jz .ends
    cmp rdx, r8
    jne .bad                        ; the last line is not one width long
    inc rcx                         ; the last line, without "\n"
.ends:                              ; each line ends with "\n" where its width says
    mov rdx, [rsi - 8]
    mov rbx, r8
    mov rax, r10
.end_loop:
    test rax, rax
    jz .count
    cmp byte [rsi + rbx], 10
    jne .bad
    add rbx, r9
    dec rax
    jmp .end_loop
.count:                             ; and there is no other one: count them all, 8 bytes at a time
    push rcx
    push r10
    mov r9, 0x0A0A0A0A0A0A0A0A
    mov r10, 0x7F7F7F7F7F7F7F7F
    mov r11, 0x0101010101010101
    xor ecx, ecx                    ; line breaks seen
    xor ebx, ebx
.word:
    lea rax, [rbx + 8]
    cmp rax, rdx
    ja .tail
    mov rax, [rsi + rbx]
    xor rax, r9                     ; a "\n" byte is now 0
    mov r8, rax
    and r8, r10
    add r8, r10
    or r8, rax
    or r8, r10                      ; the high bit is 0 exactly in the zero bytes
    not r8
    shr r8, 7
    imul r8, r11
    shr r8, 56                      ; how many
    add rcx, r8
    add rbx, 8
    jmp .word
.tail:
    cmp rbx, rdx
    jae .counted
    cmp byte [rsi + rbx], 10
    jne .tail_next
    inc rcx
.tail_next:
    inc rbx
    jmp .tail
.counted:
    pop r10
    mov rax, rcx
    pop rcx
    cmp rax, r10
    jne .bad                        ; a line break inside a line
    mov rax, rcx
    pop r11
    pop rbx
    ret
.none:
    xor eax, eax
    pop r11
    pop rbx
    ret
.bad:
    mov rax, -1
    pop r11
    pop rbx
    ret

; rt_rec_parse: rax = text, rcx = where the line starts, rdx = schema ([n, type, width, …]:
; 1 INT, 2 BOOL, 3 STRING, 4 FLOAT) → rax = a new ARRAY of n slots (the record), or -1 when a
; field is not plain (an error, a FLOAT with an exponent or more than 15 digits, an INT that
; overflows): then the prelude reads that line its own way, with its messages. INT, BOOL and
; FLOAT fields drop the spaces around; STRING keeps the leading ones. FLOAT: Clinger's fast
; path, m × 10^-k with m < 10^15 and k <= 22, one correctly rounded division, the same
; bits as the exact conversion.
; A record is one block: its n slots, then each STRING field's text (its length word, its
; bytes and a 0), which the slot points to. The collector keeps a block
; for a pointer into its middle, so a text taken out of the record keeps the block alive.
rt_rec_parse:
    push rbx
    push rbp
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8                      ; [rsp]: where the next text goes
    mov rbx, rax                    ; the text (kept alive in a register)
    mov r13, rcx                    ; position of the current field
    mov r14, rdx                    ; the schema
    mov rcx, [r14]                  ; n slots …
    xor r9d, r9d
    mov r10, r13                    ; where field i starts
.size:
    cmp r9, [r14]
    jae .sized
    mov r8, r9
    shl r8, 4
    mov rdx, [r14 + r8 + 16]        ; its width
    cmp qword [r14 + r8 + 8], 3
    jne .size_next
    lea r11, [r10 + rdx]            ; … and, for a STRING, 1 + (length + 8) / 8, the length
    mov rax, 0x2020202020202020     ; without the spaces at its end (8 at a time, then 1)
.size_trim8:
    lea r8, [r11 - 8]
    cmp r8, r10
    jl .size_trim
    cmp [rbx + r8], rax
    jne .size_trim
    mov r11, r8
    jmp .size_trim8
.size_trim:
    cmp r11, r10
    jbe .size_len
    cmp byte [rbx + r11 - 1], ' '
    jne .size_len
    dec r11
    jmp .size_trim
.size_len:
    sub r11, r10
    add r11, 16
    shr r11, 3
    add rcx, r11
.size_next:
    add r10, rdx
    inc r9
    jmp .size
.sized:
    call rt_alloc
    mov rcx, [r14]
    mov [rax - 8], rcx
    mov r15, rax                    ; the record
    lea rcx, [rax + rcx * 8]
    mov [rsp], rcx
    xor ebp, ebp                    ; field i
.field:
    cmp rbp, [r14]
    jae .ok
    mov rax, rbp
    shl rax, 4
    mov r12, [r14 + rax + 8]        ; type
    mov rdi, [r14 + rax + 16]       ; width
    mov rsi, r13                    ; a
    add rdi, r13                    ; b
    add r13, [r14 + rax + 16]       ; the next field starts after this one
    cmp r12, 3
    je .trim_end
.trim_start:
    cmp rsi, rdi
    jae .trim_end
    cmp byte [rbx + rsi], ' '
    jne .trim_end
    inc rsi
    jmp .trim_start
.trim_end:
    mov rax, 0x2020202020202020     ; 8 spaces at a time, then 1
.trim_end8:
    lea r8, [rdi - 8]
    cmp r8, rsi
    jl .trim_end1
    cmp [rbx + r8], rax
    jne .trim_end1
    mov rdi, r8
    jmp .trim_end8
.trim_end1:
    cmp rdi, rsi
    jbe .trimmed
    cmp byte [rbx + rdi - 1], ' '
    jne .trimmed
    dec rdi
    jmp .trim_end1
.trimmed:
    cmp r12, 1
    je .int
    cmp r12, 2
    je .bool
    cmp r12, 3
    je .string
    ; ---- FLOAT
    xor eax, eax
    cmp rsi, rdi
    je .store                       ; empty: 0
    xor r8d, r8d                    ; negative?
    movzx ecx, byte [rbx + rsi]
    cmp cl, '-'
    jne .f_plus
    mov r8d, 1
    inc rsi
    jmp .f_start
.f_plus:
    cmp cl, '+'
    jne .f_start
    inc rsi
.f_start:
    xor eax, eax                    ; m
    xor r9d, r9d                    ; significant digits
    xor r10d, r10d                  ; power of ten (0 or negative)
    xor r11d, r11d                  ; a digit was seen
.f_int:
    cmp rsi, rdi
    jae .f_end
    movzx ecx, byte [rbx + rsi]
    sub ecx, '0'
    cmp ecx, 9
    ja .f_dot
    call .f_digit
    jc .fallback
    inc rsi
    jmp .f_int
.f_dot:
    cmp ecx, '.' - '0'
    jne .fallback                   ; an exponent or something else
    inc rsi
.f_frac:
    cmp rsi, rdi
    jae .f_end
    movzx ecx, byte [rbx + rsi]
    sub ecx, '0'
    cmp ecx, 9
    ja .fallback
    call .f_digit
    jc .fallback
    dec r10
    inc rsi
    jmp .f_frac
.f_end:
    test r11, r11
    jz .fallback                    ; no digit: not a number
    cmp r10, -22
    jl .fallback
    test rax, rax
    jz .f_sign                      ; zero (with its sign)
    cvtsi2sd xmm0, rax
    neg r10
    lea rcx, [rel pow10_table]
    divsd xmm0, [rcx + r10 * 8]
    movq rax, xmm0
.f_sign:
    test r8, r8
    jz .store
    bts rax, 63
    jmp .store
.f_digit:                           ; ecx = digit: into m, unless there are already 15 (CF = 1)
    mov r11d, 1
    test rax, rax
    jnz .f_count
    test ecx, ecx
    jz .f_digit_ok                  ; a leading zero does not count
.f_count:
    cmp r9, 15
    jae .f_too_many
    inc r9
    imul rax, rax, 10
    add rax, rcx
.f_digit_ok:
    clc
    ret
.f_too_many:
    stc
    ret
    ; ---- INT
.int:
    xor eax, eax
    cmp rsi, rdi
    je .store                       ; empty: 0
    xor r8d, r8d
    movzx ecx, byte [rbx + rsi]
    cmp cl, '-'
    jne .i_plus
    mov r8d, 1
    inc rsi
    jmp .i_digits
.i_plus:
    cmp cl, '+'
    jne .i_digits
    inc rsi
.i_digits:
    cmp rsi, rdi
    je .fallback                    ; a sign alone
.i_loop:
    cmp rsi, rdi
    jae .i_end
    movzx ecx, byte [rbx + rsi]
    sub ecx, '0'
    cmp ecx, 9
    ja .fallback
    imul rax, rax, 10
    jo .fallback                    ; too big (the prelude says so, or reads the smallest INT)
    add rax, rcx
    jo .fallback
    inc rsi
    jmp .i_loop
.i_end:
    test r8, r8
    jz .store
    neg rax
    jmp .store
    ; ---- BOOL
.bool:
    xor eax, eax
    mov rcx, rdi
    sub rcx, rsi
    jz .store                       ; empty: false
    cmp rcx, 1
    jne .fallback
    movzx ecx, byte [rbx + rsi]
    cmp cl, 'F'
    je .store
    cmp cl, 'T'
    jne .fallback
    mov eax, 1
    jmp .store
    ; ---- STRING
.string:                            ; into the record's block, after its slots
    mov r12, rdi
    sub r12, rsi                    ; length
    mov rax, [rsp]
    mov [rax], r12
    add rax, 8                      ; the text
    mov rdi, rax
    lea rsi, [rbx + rsi]
    mov rcx, r12
    rep movsb
    lea rcx, [r12 + 8]              ; the next text after this one and a 0
    shr rcx, 3
    lea rcx, [rax + rcx * 8]
    mov [rsp], rcx
.store:
    mov [r15 + rbp * 8], rax
    inc rbp
    jmp .field
.ok:
    mov rax, r15
    jmp .end
.fallback:
    mov rax, -1
.end:
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    pop rbx
    ret

; json_skip_string: rsi = bytes, rdx = n, rbx = the opening quote → rbx after the closing
; quote, or -1 if the string does not end
json_skip_string:
    inc rbx
.loop:
    cmp rbx, rdx
    jae .bad
    movzx eax, byte [rsi + rbx]
    cmp al, '"'
    je .done
    inc rbx
    cmp al, 92                      ; a backslash: skip what it escapes
    jne .loop
    inc rbx
    jmp .loop
.done:
    inc rbx
    ret
.bad:
    mov rbx, -1
    ret

; rt_syscall: rax = ARRAY of INT [n, a1 … a6] → rax = what the kernel gave (-errno on an
; error). For the prelude only (directories and processes are coming). Missing arguments are 0.
rt_syscall:
    push rbx
    mov rbx, rax
    mov rcx, [rbx - 8]              ; how many: n and up to six arguments
    xor edi, edi
    xor esi, esi
    xor edx, edx
    xor r10d, r10d
    xor r8d, r8d
    xor r9d, r9d
    cmp rcx, 2
    jb .go
    mov rdi, [rbx + 8]
    cmp rcx, 3
    jb .go
    mov rsi, [rbx + 16]
    cmp rcx, 4
    jb .go
    mov rdx, [rbx + 24]
    cmp rcx, 5
    jb .go
    mov r10, [rbx + 32]
    cmp rcx, 6
    jb .go
    mov r8, [rbx + 40]
    cmp rcx, 7
    jb .go
    mov r9, [rbx + 48]
.go:
    mov rax, [rbx]
    syscall
    pop rbx
    ret

; rt_array_concat: rax = a, rcx = b (ARRAYs of one type) → a new ARRAY with
; the elements of a and then those of b
rt_array_concat:
    push rbx
    push r12
    mov rbx, rax
    mov r12, rcx
    mov rcx, [rbx - 8]
    add rcx, [r12 - 8]
    call rt_alloc
    mov rdi, rax
    mov rsi, rbx
    mov rcx, [rbx - 8]
    rep movsq
    mov rsi, r12
    mov rcx, [r12 - 8]
    rep movsq
    pop r12
    pop rbx
    ret

; rt_int_text: rax = INT → rax = a new STRING with it in decimal ($n)
rt_int_text:
    push rbx
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal                 ; rsi = the first character
    lea rbx, [rsp + 32]
    sub rbx, rsi                    ; length
    push rsi
    lea rcx, [rbx + 8]
    shr rcx, 3
    call rt_alloc
    pop rsi
    mov [rax - 8], rbx
    mov rdi, rax
    mov rcx, rbx
    rep movsb
    add rsp, 32
    pop rbx
    ret

rt_print_bool:
    test rax, rax
    jz .falso_
    lea rsi, [rel s_true]
    mov edx, 4
    jmp rt_buffer
.falso_:
    lea rsi, [rel s_false]
    mov edx, 5
    jmp rt_buffer

rt_print_str:
    mov rsi, rax
    mov rdx, [rax - 8]
    jmp rt_buffer

; rt_buffer: rsi = ptr, rdx = len — copies into the buffer, flushing it when full
rt_buffer:
.repeat:
    test rdx, rdx
    jz .finish
    mov rax, [OUTPUT_SIZE]
    mov ecx, OUTPUT_CAP
    sub rcx, rax                    ; free space
    jnz .copy
    push rsi
    push rdx
    call rt_flush
    pop rdx
    pop rsi
    jmp .repeat
.copy:
    cmp rcx, rdx
    jbe .count
    mov rcx, rdx
.count:
    mov rdi, OUTPUT_BUF
    add rdi, rax
    add rax, rcx
    mov [OUTPUT_SIZE], rax
    sub rdx, rcx
    rep movsb
    jmp .repeat
.finish:
    ret

rt_flush:
    mov rdx, [OUTPUT_SIZE]
    test rdx, rdx
    jz .finish
    mov edi, 1
    mov rsi, OUTPUT_BUF
    call rt_write_fd
    mov qword [OUTPUT_SIZE], 0
.finish:
    ret

; rt_write_fd: edi = fd, rsi = ptr, rdx = len (gives up on error). While a runtime error
; is being caught (ERR_CAPTURE), what goes to fd 2 goes into ?!'s text instead.
rt_write_fd:
    cmp edi, 2
    jne .repeat
    cmp qword [ERR_CAPTURE], 0
    jne .capture
.repeat:
    test rdx, rdx
    jz .finish
    mov eax, 1                      ; sys_write
    syscall
    test rax, rax
    jle .finish
    add rsi, rax
    sub rdx, rax
    jmp .repeat
.finish:
    ret
.capture:                           ; appended to the text, up to 4000 bytes
    push rdi
    mov rdi, [PROT_BASE]
    add rdi, 4096
    add rdi, [ERR_LEN]
    mov rcx, 4000
    sub rcx, [ERR_LEN]
    cmp rdx, rcx
    jbe .fits
    mov rdx, rcx
.fits:
    add [ERR_LEN], rdx
    mov rcx, rdx
    rep movsb
    pop rdi
    ret

; ---- protected calls (SPEC §25) -------------------------------------------------
; A runtime error starts with rt_err_begin and ends with rt_err_end. With no protection active
; they write "nihil: …" and end the program with 2; inside a protected call the text goes to
; ?! and rt_err_end resumes after the call, with the stack and the registers it had.
rt_err_begin:
    cmp qword [PROT_DEPTH], 0
    je .plain
    mov qword [ERR_LEN], 0
    mov qword [ERR_CAPTURE], 1
    ret
.plain:
    call rt_flush
    mov edi, 2
    lea rsi, [rel s_nihil]
    mov edx, s_nihil_len
    jmp rt_write_fd

rt_err_end:
    cmp qword [ERR_CAPTURE], 0
    jne .resume
    call gc_stop_child
    mov eax, 60
    mov edi, 2
    syscall
.resume:
    mov qword [ERR_CAPTURE], 0
    mov rcx, [ERR_LEN]              ; the text without its final line break
    test rcx, rcx
    jz .pop
    mov rsi, [PROT_BASE]
    cmp byte [rsi + 4096 + rcx - 1], 10
    jne .pop
    dec qword [ERR_LEN]
.pop:
    dec qword [PROT_DEPTH]
    mov rcx, [PROT_DEPTH]
    shl rcx, 6
    add rcx, [PROT_BASE]
    mov rsp, [rcx]
    mov rbp, [rcx + 8]
    mov rbx, [rcx + 24]
    mov r12, [rcx + 32]
    mov r13, [rcx + 40]
    mov r14, [rcx + 48]
    mov r15, [rcx + 56]
    xor eax, eax
    xor edx, edx
    jmp [rcx + 16]

; rt_protect: rax = where to resume. Keeps the caller's stack pointer (after this call
; returns), its frame and the optimizer's registers.
rt_protect:
    cmp qword [PROT_BASE], 0
    jne .ready
    push rax
    mov esi, 8192
    call gc_mmap
    cmp rax, -4096
    jae .no_memory
    mov [PROT_BASE], rax
    pop rax
.ready:
    mov rcx, [PROT_DEPTH]
    cmp rcx, 64
    jae .too_deep
    shl rcx, 6
    add rcx, [PROT_BASE]
    lea rdx, [rsp + 8]
    mov [rcx], rdx
    mov [rcx + 8], rbp
    mov [rcx + 16], rax
    mov [rcx + 24], rbx
    mov [rcx + 32], r12
    mov [rcx + 40], r13
    mov [rcx + 48], r14
    mov [rcx + 56], r15
    inc qword [PROT_DEPTH]
    ret
.too_deep:
    lea rsi, [rel s_too_deep]
    jmp rt_error
.no_memory:
    lea rsi, [rel s_without_memory]
    jmp rt_error

rt_unprotect:                       ; keeps rax and rdx
    dec qword [PROT_DEPTH]
    mov qword [ERR_LEN], 0
    ret

; rt_err_text → rax = ?! (a new STRING)
rt_err_text:
    push rbx
    mov rbx, [ERR_LEN]
    lea rcx, [rbx + 8]
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], rbx
    test rbx, rbx
    jz .empty
    mov rdi, rax
    mov rsi, [PROT_BASE]
    add rsi, 4096
    mov rcx, rbx
    rep movsb
.empty:
    pop rbx
    ret

; rt_fail: rax = STRING → a runtime error with that message (the prelude's errors)
rt_fail:
    push rax
    call rt_err_begin
    mov rsi, [rsp]
    mov rdx, [rsi - 8]
    mov edi, 2
    call rt_write_fd
    pop rax
    mov edi, 2
    lea rsi, [rel s_nl]
    mov edx, 1
    call rt_write_fd
    jmp rt_err_end

; ---- termination ----------------------------------------------------------------
rt_exit:                            ; rdi = exit code
    push rdi
    call rt_flush
    call gc_stop_child
    pop rdi
    mov eax, 60                     ; sys_exit
    syscall

; rt_error: rsi = message (0-terminated). Writes "nihil: <msg>\n" to stderr
; and exits with code 2 (SPEC §8.3).
rt_error:
    push rsi
    lea rcx, [rel s_without_memory]
    cmp rsi, rcx
    jne .catchable
    mov qword [PROT_DEPTH], 0       ; out of memory is never caught: the heap may be inconsistent
.catchable:
    call rt_err_begin
    pop rsi
    xor edx, edx
.size:
    cmp byte [rsi + rdx], 0
    je .write
    inc rdx
    jmp .size
.write:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_nl]
    mov edx, 1
    call rt_write_fd
    jmp rt_err_end

; ---- arrays and heap ----------------------------------------------------------
; An array is [length: 8 bytes][8-byte elements]; the value of the array points
; to the first element. A STRING is the same block with its length in bytes.
;
; Garbage collector: conservative mark and sweep. Values carry no type at run
; time, so every qword in the registers, on the stack, in the globals and in a
; live block is taken as a possible reference: if it points into a block of the
; heap, that block stays. What no path reaches is freed and its memory used again.
;
; The heap is one reservation of address space (64 GiB, or less if refused) in
; 64 KiB pages, each described by one qword in GC_DESC:
;   0           free (or never used)
;   PD_SMALL    blocks of one size class (class in the bits above the kind)
;   PD_LARGE    first page of a large block (its pages above the kind)
;   PD_CONT     a later page of a large block (pages back to the first one)
;   PD_DIRTY    an empty page of small blocks kept for reuse without giving it
;               back (up to GC_KEEP of them): its old bytes are cleared on reuse
; Small blocks (up to 32 KiB) come in 21 size classes: 32, 48, 64, 96, 128 …
; 32768 bytes. A block starts with a header [n << 8 | marked << 1 | used] and
; then the length word the program sees, so the value points 16 bytes in.
; Free small blocks have header 0 and link to the next free one at +8.
; New memory is always zero: fresh pages come zeroed from the kernel, freed
; pages are given back with madvise(MADV_DONTNEED) (zero again when touched),
; and a reused small block is cleared before it is handed out. A large block
; is scanned only on the pages that hold something (/proc/self/pagemap: present
; or swapped): a big array never written costs nothing, as before. mincore is
; not enough: it says 0 for a page in swap, and skipping that page freed the
; blocks it pointed to. mincore stays the fallback when pagemap cannot be read.
%define GC_PAGE_SHIFT 16
%define GC_PAGE       (1 << GC_PAGE_SHIFT)
%define GC_SMALL_MAX  32768
%ifdef GC_STRESS                    ; make gcstress: a collection every 256 KiB
%define GC_MIN        (256 << 10)
%else
%define GC_MIN        (16 << 20)    ; collect after at least 16 MiB of new blocks
%endif
%define GC_RESERVE    (64 << 30)
; from this heap size on, a collection is marked by a child process while the program goes on
; (gc_fork); the program looks for its end every GC_POLL bytes of new blocks
%ifdef GC_STRESS
%define GC_FORK_MIN   (1 << 20)
%define GC_POLL       (256 << 10)
%define GC_SWEEP_STEP 4
%define GC_GIVE_STEP  4
%else
%define GC_FORK_MIN   (64 << 20)
%define GC_POLL       (4 << 20)
%define GC_SWEEP_STEP 64            ; pages swept at a time after a forked marking (4 MiB)
%define GC_GIVE_STEP  256           ; free pages given back to the kernel at a time (16 MiB)
%endif
%define RUN_PENDING   63            ; a run's bit: its pages were not given back yet (not zero)
%define PD_SMALL 1
%define PD_LARGE 2
%define PD_CONT  3
%define PD_DIRTY 4
%define PD_FRESH 0x80               ; a small page handed out ahead of a sweep in steps (gc_small_page)
%define GC_KEEP  (GC_MIN >> GC_PAGE_SHIFT)   ; empty small pages kept: 16 MiB

rt_alloc:                           ; rcx = n → rax (keeps every register but rax, rdx, r8)
    test rcx, rcx
    js .negativo
    mov rax, 1 << 40
    cmp rcx, rax
    jae .large
    push rcx
    push rsi
    push rdi
    push r9
    push r10
    push r11
    cmp qword [GC_STATE], 0
    jne .ready
    call gc_init
.ready:
    mov r11, rcx                    ; n
    lea rdx, [rcx * 8 + 16]         ; bytes, with the header and the length
    add [GC_ALLOCATED], rdx
    mov rax, [GC_ALLOCATED]
    cmp rax, [GC_THRESHOLD]
    jbe .alloc
    call gc_collect                 ; keeps every register
.alloc:
    cmp rdx, GC_SMALL_MAX
    ja .big
    xor r8d, r8d                    ; the size class: 32, 48, 64, 96, 128, 192 …
    cmp rdx, 32
    jbe .class
    lea r9, [rdx - 1]
    bsr r9, r9                      ; 2^b < bytes <= 2^(b+1)
    lea ecx, [r9 - 1]
    mov r10d, 3
    shl r10, cl                     ; 3 · 2^(b-1)
    lea r8, [r9 * 2 - 9]
    cmp rdx, r10
    jbe .class
    inc r8                          ; 2^(b+1)
.class:
    mov rax, [GC_FREE + r8 * 8]
    test rax, rax
    jnz .take
    cmp qword [GC_SWEEPING], 0
    je .new_page
    mov eax, GC_SWEEP_STEP          ; a sweep in steps: the next pages may free blocks of this class
    call gc_sweep_step
    mov rax, [GC_FREE + r8 * 8]
    test rax, rax
    jnz .take
.new_page:
    call gc_small_page              ; a new page of free blocks of class r8
    mov rax, [GC_FREE + r8 * 8]
.take:
    mov r9, [rax + 8]
    mov [GC_FREE + r8 * 8], r9
    mov r9, rax                     ; clear the n elements (and the 0 after a STRING)
    lea rdi, [rax + 16]
    mov rcx, r11
    xor eax, eax
    rep stosq
    mov rax, r9
    jmp .header
.big:
    lea rcx, [rdx + GC_PAGE - 1]
    shr rcx, GC_PAGE_SHIFT          ; pages
    call gc_get_pages
    test rax, rax
    jnz .pages
    mov rax, 0x7FFFFFFFFFFFFFFF     ; no page left: the memory is needed now (gc_collect waits)
    mov [GC_THRESHOLD], rax
    call gc_collect
    call gc_get_pages
    test rax, rax
    jz .without_memory
.pages:                             ; zero already: only the descriptors and the header
    mov r9, rax
    sub r9, [GC_HEAP_BASE]
    shr r9, GC_PAGE_SHIFT
    mov rdi, [GC_DESC]
    lea rdi, [rdi + r9 * 8]
    mov r10, rcx
    shl r10, 8
    or r10, PD_LARGE
    mov [rdi], r10
    mov r10d, 1
.cont:
    cmp r10, rcx
    jae .header
    mov r9, r10
    shl r9, 8
    or r9, PD_CONT
    mov [rdi + r10 * 8], r9
    inc r10
    jmp .cont
.header:
    cmp qword [GC_MAP], 0           ; a forked collection under way (marking, or sweeping in
    je .unmarked                    ; steps): the new block is live (the map)
    mov rcx, rax
    sub rcx, [GC_HEAP_BASE]
    cmp rcx, [GC_SNAP]
    jae .unmarked                   ; past the heap it saw: not swept this time
    shr rcx, 5
    add rcx, [GC_MAP]
    mov byte [rcx], 1
.unmarked:
    mov rcx, r11
    shl rcx, 8
    or rcx, 1                       ; used
    mov [rax], rcx
    mov [rax + 8], r11              ; the length
    add rax, 16
    pop r11
    pop r10
    pop r9
    pop rdi
    pop rsi
    pop rcx
    ret
.negativo:
    lea rsi, [rel s_size_negativo]
    jmp rt_error
.large:
    lea rsi, [rel s_size_large]
    jmp rt_error
.without_memory:
    lea rsi, [rel s_without_memory]
    jmp rt_error

gc_class_size:
    dq 32, 48, 64, 96, 128, 192, 256, 384, 512, 768, 1024, 1536, 2048, 3072
    dq 4096, 6144, 8192, 12288, 16384, 24576, 32768

; r8 = class: puts a new page of free blocks of that class in its list
; (collecting first if there is no page left). Keeps every register but rax.
gc_small_page:
    push rcx
    push rdx
    push rsi
    push r9
    push r10
    mov rax, [GC_NDIRTY]            ; an empty page kept from a collection
    test rax, rax
    jz .fresh
    dec rax
    mov [GC_NDIRTY], rax
    mov rcx, [GC_DIRTY]
    mov rax, [rcx + rax * 8]
    shl rax, GC_PAGE_SHIFT
    add rax, [GC_HEAP_BASE]
    jmp .carve
.fresh:
    mov ecx, 1
    call gc_get_pages
    test rax, rax
    jnz .carve
    mov rax, 0x7FFFFFFFFFFFFFFF     ; no page left: the memory is needed now (gc_collect waits)
    mov [GC_THRESHOLD], rax
    call gc_collect
    cmp qword [GC_FREE + r8 * 8], 0 ; the collection may have freed blocks of this class
    jne .done
    mov ecx, 1
    call gc_get_pages
    test rax, rax
    jz rt_alloc.without_memory
.carve:
    mov rsi, rax                    ; the page
    mov rcx, rax
    sub rcx, [GC_HEAP_BASE]
    shr rcx, GC_PAGE_SHIFT
    mov r9, [GC_DESC]
    mov r10, r8
    shl r10, 8
    or r10, PD_SMALL
    cmp qword [GC_SWEEPING], 0      ; a page ahead of a sweep in steps: its blocks go in the list now,
    je .desc                        ; so that sweep must not put them there again; it skips the page
    cmp rcx, [GC_SWEEP_POS]         ; (PD_FRESH), and its last step clears the mark
    jb .desc
    cmp rcx, [GC_SWEEP_END]
    jae .desc
    or r10, PD_FRESH
.desc:
    mov [r9 + rcx * 8], r10
    lea r9, [rel gc_class_size]
    mov r9, [r9 + r8 * 8]           ; block size
    mov eax, GC_PAGE
    xor edx, edx
    div r9
    imul rax, r9                    ; past the last block that fits
    xor r10d, r10d                  ; the list, built from the end
.link:
    sub rax, r9
    lea rcx, [rsi + rax]
    mov qword [rcx], 0              ; free (a kept page still has old bytes)
    mov [rcx + 8], r10
    mov r10, rcx
    test rax, rax
    jnz .link
    mov [GC_FREE + r8 * 8], r10
.done:
    pop r10
    pop r9
    pop rsi
    pop rdx
    pop rcx
    ret

; rcx = pages → rax = the first one (zeroed memory), or 0 if there is no room.
; First fit among the runs of free pages, else new pages. Pages of a run still pending (RUN_PENDING:
; freed by a sweep and not given back to the kernel yet) are given back first, so they come zero.
; Keeps rcx; uses rdx, r9, r10.
gc_get_pages:
    mov r9, [GC_RUNS]
    xor r10d, r10d
.find:
    cmp r10, [GC_NRUNS]
    jae .new
    mov rax, r10
    shl rax, 4
    mov rdx, [r9 + rax + 8]         ; its pages
    btr rdx, RUN_PENDING
    cmp rdx, rcx
    jae .take
    inc r10
    jmp .find
.take:
    add r9, rax                     ; the run
    push qword [r9 + 8]             ; whether it is pending (its bit)
    mov rax, [r9]                   ; its first page
    sub rdx, rcx
    jz .whole
    mov r10, [rsp]                  ; what is left starts after the pages taken (pending as it was)
    shr r10, RUN_PENDING
    shl r10, RUN_PENDING
    or rdx, r10
    mov [r9 + 8], rdx
    lea rdx, [rax + rcx]
    mov [r9], rdx
    jmp .address
.whole:                             ; the last run takes its place
    mov rdx, [GC_NRUNS]
    dec rdx
    mov [GC_NRUNS], rdx
    shl rdx, 4
    add rdx, [GC_RUNS]
    mov r10, [rdx]
    mov [r9], r10
    mov r10, [rdx + 8]
    mov [r9 + 8], r10
.address:
    shl rax, GC_PAGE_SHIFT
    add rax, [GC_HEAP_BASE]
    pop rdx
    bt rdx, RUN_PENDING
    jnc .ready
    push rax                        ; pending: given back now, so the pages come zero
    push rcx
    push rsi
    push rdi
    push r11
%ifdef GC_STATS
    push rax
    call gc_now_us
    mov [GC_STAT_STEPT0], rax
    pop rax
%endif
    mov rdi, rax
    mov rsi, rcx
    shl rsi, GC_PAGE_SHIFT
    mov eax, 28                     ; sys_madvise(pages, bytes, MADV_DONTNEED)
    mov edx, 4
    syscall
%ifdef GC_STATS
    call gc_now_us
    sub rax, [GC_STAT_STEPT0]
    lea rsi, [rel s_gcs_zero]
    mov edx, s_gcs_zero_len
    call gc_slow_stats
%endif
    pop r11
    pop rdi
    pop rsi
    pop rcx
    pop rax
.ready:
    ret
.new:
    mov rax, [GC_BUMP]
    mov rdx, rcx
    shl rdx, GC_PAGE_SHIFT
    add rdx, rax
    cmp rdx, [GC_HEAP_LIMIT]
    ja .none
    mov [GC_BUMP], rdx
    ret
.none:
    xor eax, eax
    ret

; gc_mmap: rsi = bytes → rax = new zeroed memory (address space only), or a
; negative errno. Uses rcx, rdx, rdi, r8–r11.
gc_mmap:
    mov eax, 9                      ; sys_mmap
    xor edi, edi
    mov edx, 3                      ; PROT_READ | PROT_WRITE
    mov r10d, 0x4022                ; MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE
    mov r8, -1
    xor r9d, r9d
    syscall
    ret

; the first allocation: reserves the heap and its tables, finds the roots
gc_init:
    push rax
    push rcx
    push rdx
    push rsi
    push rdi
    push r8
    push r9
    push r10
    push r11
    push rbx
    mov rbx, GC_RESERVE
.reserve:
    lea rsi, [rbx + GC_PAGE]        ; one page more, to align the start
    call gc_mmap
    cmp rax, -4096
    jb .reserved
    shr rbx, 2                      ; refused: a quarter of that
    cmp rbx, 64 << 20
    jae .reserve
    jmp rt_alloc.without_memory
.reserved:
    add rax, GC_PAGE - 1
    and rax, -GC_PAGE
    mov [GC_HEAP_BASE], rax
    mov [GC_BUMP], rax
    add rax, rbx
    mov [GC_HEAP_LIMIT], rax
    mov rdi, [GC_HEAP_BASE]         ; huge pages for the heap (2 MiB) where the kernel has them: a fork
    mov rsi, rbx                    ; copies far fewer page entries (2.9 → 0.3 ms with 200 MB of heap),
    mov eax, 28                     ; and the benchmark ran 9% faster with a little less memory
    mov edx, 14                     ; sys_madvise(heap, bytes, MADV_HUGEPAGE); refused: no matter
    syscall
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 3      ; 8 bytes per page
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_DESC], rax
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 4      ; 16 bytes per run
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_RUNS], rax
    mov rsi, rbx
    shr rsi, 2                      ; a block has at least 32 bytes: 8 per block
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_MSTACK], rax
    add rax, rsi
    mov [GC_MSTACK_END], rax
    mov rsi, rbx
    shr rsi, GC_PAGE_SHIFT - 3      ; kept pages: 8 bytes per page
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_DIRTY], rax
    mov rsi, rbx
    shr rsi, 12                     ; mincore: a byte per 4 KiB
    call gc_mmap
    cmp rax, -4096
    jae rt_alloc.without_memory
    mov [GC_MINCORE], rax
    mov rax, [BASE_CODE + 64 + 56 + 16]   ; the data PT_LOAD: p_vaddr …
    add rax, [BASE_CODE + 64 + 56 + 40]   ; … + p_memsz
    mov [GC_DATA_END], rax
    call gc_stack_top
    mov [GC_STACK_TOP], rax
    mov rax, GC_MIN
    cmp qword [GC_STACK_TOP], 0
    jne .threshold
    mov rax, -1                     ; roots unknown: never collect
    shr rax, 1
.threshold:
    mov [GC_THRESHOLD], rax
    mov qword [GC_STATE], 1
    pop rbx
    pop r11
    pop r10
    pop r9
    pop r8
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rax
    ret

; → rax = an address above every frame of the program's stack, or 0: the end of the mapping
; of /proc/self/maps that holds the stack pointer. (AT_EXECFN, the file name the kernel puts at
; the top of the stack, is not used: under Rosetta, which runs x86_64 programs on Apple silicon,
; it points outside the program's stack.)
gc_stack_top:
    push rbx
    push r12
    push r13
    mov r13, rsp                    ; an address in the program's stack
    mov rsi, 1 << 20                ; the file, read into a temporary block
    call gc_mmap
    cmp rax, -4096
    jae .none
    mov rbx, rax
    lea rsi, [rel s_maps]
    mov eax, 257                    ; sys_openat(AT_FDCWD, "/proc/self/maps", O_RDONLY)
    mov rdi, -100
    xor edx, edx
    syscall
    test rax, rax
    js .free
    mov r12, rax
    xor ecx, ecx                    ; bytes read
.read:
    push rcx
    xor eax, eax                    ; sys_read
    mov rdi, r12
    lea rsi, [rbx + rcx]
    mov rdx, (1 << 20) - 1
    sub rdx, rcx
    syscall
    pop rcx
    test rax, rax
    jle .close
    add rcx, rax
    cmp rcx, (1 << 20) - 1
    jb .read
.close:
    push rcx
    mov eax, 3
    mov rdi, r12
    syscall
    pop rcx
    xor edx, edx                    ; position: the start of a line "start-end perms …"
.line:
    cmp rdx, rcx
    jae .not_found
    call .hex                       ; rax = start
    mov r10, rax
    cmp rdx, rcx
    jae .not_found
    cmp byte [rbx + rdx], '-'
    jne .skip
    inc rdx
    call .hex                       ; rax = end
    cmp r13, r10
    jb .skip
    cmp r13, rax
    jb .found                       ; start <= rsp < end: this mapping holds the stack
.skip:                              ; to the next line
    cmp rdx, rcx
    jae .not_found
    cmp byte [rbx + rdx], 10
    je .next_line
    inc rdx
    jmp .skip
.next_line:
    inc rdx
    jmp .line
.hex:                               ; the hexadecimal at rdx → rax (rdx after it)
    xor eax, eax
.digit:
    cmp rdx, rcx
    jae .hex_end
    movzx r8d, byte [rbx + rdx]
    sub r8d, '0'
    cmp r8d, 9
    jbe .add
    sub r8d, 'a' - '0' - 10
    cmp r8d, 10
    jb .hex_end
    cmp r8d, 15
    ja .hex_end
.add:
    shl rax, 4
    add rax, r8
    inc rdx
    jmp .digit
.hex_end:
    ret
.not_found:
    xor eax, eax
.found:
    push rax
    mov eax, 11                     ; sys_munmap
    mov rdi, rbx
    mov rsi, 1 << 20
    syscall
    pop rax
    jmp .end
.free:
    mov eax, 11
    mov rdi, rbx
    mov rsi, 1 << 20
    syscall
.none:
    xor eax, eax
.end:
    pop r13
    pop r12
    pop rbx
    ret

; a collection: keeps every register (they are roots, so they go on the stack
; that is scanned)
; a collection (keeps every register). A heap of GC_FORK_MIN or more is marked by a child process
; (gc_fork) while the program goes on, and swept when the child has ended (gc_finish); while it
; marks, a call here looks whether it ended, and waits for it when the program needs the memory
; (called with GC_ALLOCATED at or below the threshold: no page left) or has made as many new bytes
; as the heap had. A smaller heap, or a fork that fails, is collected here at once.
gc_collect:
    push rax
    push rbx
    push rcx
    push rdx
    push rsi
    push rdi
    push rbp
    push r8
    push r9
    push r10
    push r11
    push r12
    push r13
    push r14
    push r15
    cmp qword [GC_SWEEPING], 0
    je .not_sweeping
    mov rax, [GC_ALLOCATED]         ; a sweep in steps under way: another step, or all of it when
    cmp rax, [GC_THRESHOLD]         ; no page is left
    mov rax, -1
    jbe .sweep_more
    mov eax, GC_SWEEP_STEP
.sweep_more:
    call gc_sweep_step
    cmp qword [GC_SWEEPING], 0
    je .out
    mov rax, [GC_ALLOCATED]
    add rax, GC_POLL
    mov [GC_THRESHOLD], rax
    jmp .out
.not_sweeping:
    cmp qword [GC_CHILD], 0
    jne .running
    cmp qword [GC_GIVING], 0
    je .decide
    mov rax, [GC_ALLOCATED]         ; free pages to give back: another step, unless no page is left
    cmp rax, [GC_THRESHOLD]         ; or the next collection is due
    jbe .decide
    mov eax, GC_GIVE_STEP
    call gc_give_step
    mov rax, [GC_ALLOCATED]
    cmp rax, [GC_LIMIT]
    jae .decide
    add rax, GC_POLL
    cmp rax, [GC_LIMIT]
    jbe .give_later
    mov rax, [GC_LIMIT]
.give_later:
    mov [GC_THRESHOLD], rax
    jmp .out
.decide:
    mov rax, [GC_ALLOCATED]
    cmp rax, [GC_THRESHOLD]
    jbe .now                        ; called because no page is left: collect here, now
    mov rax, [GC_BUMP]
    sub rax, [GC_HEAP_BASE]
    cmp rax, GC_FORK_MIN
    jb .now
    call gc_fork                    ; rax = 0: a child marks now
    test rax, rax
    jz .out
.now:
    call gc_collect_now
    jmp .out
.running:
    call gc_poll
.out:
    pop r15
    pop r14
    pop r13
    pop r12
    pop r11
    pop r10
    pop r9
    pop r8
    pop rbp
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rbx
    pop rax
    ret

; the threshold after a collection: as many new bytes as are in use, at least GC_MIN
gc_threshold:
    mov qword [GC_ALLOCATED], 0
%ifdef GC_STRESS
    mov eax, GC_MIN
%else
    mov rax, [GC_LIVE]
    cmp rax, GC_MIN
    jae .set
    mov eax, GC_MIN
%endif
.set:
    mov [GC_LIMIT], rax
    cmp qword [GC_GIVING], 0        ; pages to give back: gc_collect comes back sooner for them
    je .threshold
    cmp rax, GC_POLL
    jbe .threshold
    mov eax, GC_POLL
.threshold:
    mov [GC_THRESHOLD], rax
    ret

; gives back to the kernel the pages of pending runs, up to rax pages (-1: all); when no run is left
; to look at, GC_GIVING ends. A pending run that moved (gc_get_pages) is zeroed when it is taken.
; Keeps every register.
gc_give_step:
    push rax
    push rbx
    push rcx
    push rdx
    push rsi
    push rdi
    push r8
    push r9
    push r11
    mov r8, rax                     ; pages still to give back in this step
    mov rbx, [GC_GIVE_POS]
%ifdef GC_STATS
    call gc_now_us
    push rax
%endif
.run:
    cmp rbx, [GC_NRUNS]
    jae .all
    test r8, r8
    jle .paused
    mov r9, rbx
    shl r9, 4
    add r9, [GC_RUNS]
    mov rsi, [r9 + 8]
    btr rsi, RUN_PENDING
    jnc .next                       ; given back already
    mov [r9 + 8], rsi
    sub r8, rsi
    mov rdi, [r9]
    shl rdi, GC_PAGE_SHIFT
    add rdi, [GC_HEAP_BASE]
    shl rsi, GC_PAGE_SHIFT
    mov eax, 28                     ; sys_madvise(pages, bytes, MADV_DONTNEED)
    mov edx, 4
    syscall
.next:
    inc rbx
    jmp .run
.all:
    mov qword [GC_GIVING], 0
.paused:
    mov [GC_GIVE_POS], rbx
%ifdef GC_STATS
    pop rcx
    call gc_now_us
    sub rax, rcx
    lea rsi, [rel s_gcs_give]
    mov edx, s_gcs_give_len
    call gc_slow_stats
%endif
    pop r11
    pop r9
    pop r8
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rbx
    pop rax
    ret

; a collection with the program stopped: mark, then sweep
gc_collect_now:
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_T0], rax
    mov qword [GC_STAT_MARKED], 0
%endif
    call gc_mark
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_T1], rax
%endif
    call gc_sweep_begin             ; the whole sweep, now (it sets the next threshold)
    mov rax, -1
    call gc_sweep_step
    inc qword [GC_COUNT]
%ifdef GC_STATS
    call gc_stats
%endif
    ret

; marks what the registers (pushed by gc_collect), the stack and the globals reach, and what those
; blocks reach: in the blocks' headers, or in GC_MAP when GC_MAPMODE is 1 (a child). Leaves
; r12 = descriptors, r13 = heap bytes, r14 = heap (for gc_sweep_begin).
gc_mark:
    mov eax, 257                    ; sys_openat(AT_FDCWD, "/proc/self/pagemap", O_RDONLY | O_CLOEXEC)
    mov rdi, -100
    lea rsi, [rel s_pagemap]
    mov edx, 0x80000
    syscall
    inc rax                         ; fd + 1; an error gives 0 or less
    jg .pagemap
    xor eax, eax
.pagemap:
    mov [GC_PAGEMAP], rax
    mov r14, [GC_HEAP_BASE]
    mov r13, [GC_BUMP]
    sub r13, r14                    ; bytes of the heap in use (pages handed out)
    mov r12, [GC_DESC]
    mov r15, [GC_MSTACK]
    mov rsi, rsp                    ; the stack, with the registers pushed by gc_collect
    mov rdi, [GC_STACK_TOP]
    call gc_scan
    mov rsi, GLOBALS
    mov rdi, [GC_DATA_END]
    call gc_scan
.drain:                             ; the blocks reached, until none is left
    cmp r15, [GC_MSTACK]
    je .marked
    sub r15, 8
    lea rax, [r15 - 64]             ; the block 8 entries down the mark stack: into the cache now,
    cmp rax, [GC_MSTACK]            ; so it is there when its turn comes (−15% of the marking of a
    jb .drain_block                 ; large heap; a multiply instead of div, and a prefetch in
    mov rax, [rax]                  ; gc_scan, were measured too and made it slower)
    prefetcht0 [rax]
.drain_block:
    mov rbx, [r15]
    mov rcx, [rbx]
    shr rcx, 8                      ; n
    lea rsi, [rbx + 16]
    lea rdi, [rsi + rcx * 8]
    cmp rcx, GC_SMALL_MAX / 8
    ja .large
    call gc_scan
    jmp .drain
.large:
    call gc_scan_resident
    jmp .drain
.marked:
    mov rdi, [GC_PAGEMAP]
    test rdi, rdi
    jz .closed
    dec rdi
    mov eax, 3                      ; sys_close
    syscall
    mov qword [GC_PAGEMAP], 0
.closed:
    ret

; starts a collection marked by a child process: a map shared with it (a byte for every 32 bytes of
; the heap), then fork. The child marks in the map and ends; this process goes on, marking in the map
; the blocks it hands out meanwhile (rt_alloc). A block unreachable when the child forked stays
; unreachable, so whatever the map leaves unmarked is garbage. → rax = 0, or 1 if it could not start.
gc_fork:
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_T0], rax
    mov qword [GC_STAT_MARKED], 0
%endif
    mov rsi, [GC_BUMP]
    sub rsi, [GC_HEAP_BASE]
    mov [GC_SNAP], rsi
    shr rsi, 5
    add rsi, 4095
    and rsi, -4096
    mov [GC_MAP_LEN], rsi
    mov eax, 9                      ; sys_mmap(0, len, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0)
    xor edi, edi
    mov edx, 3
    mov r10d, 0x21
    mov r8, -1
    xor r9d, r9d
    syscall
    cmp rax, -4096
    jae .failed
    mov [GC_MAP], rax
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_STEPT0], rax
%endif
    mov eax, 57                     ; sys_fork
    syscall
    test rax, rax
    js .unmap
    jz .child
    mov [GC_CHILD], rax
%ifdef GC_STATS
    call gc_fork_stats
%endif
    mov qword [GC_ALLOCATED], 0
    mov qword [GC_THRESHOLD], GC_POLL
    xor eax, eax
    ret
.child:
    mov qword [OUTPUT_SIZE], 0      ; the program's pending output is not this process's to write
    mov qword [PROT_DEPTH], 0       ; an error here ends this process (no protected call to go back to)
    mov qword [ERR_CAPTURE], 0
    mov eax, 436                    ; sys_close_range(0, ~0, 0): no pipe or socket of the program kept open
    xor edi, edi
    mov esi, -1
    xor edx, edx
    syscall
    mov qword [GC_MAPMODE], 1
    call gc_mark
    mov eax, 231                    ; sys_exit_group(0): the map is marked
    xor edi, edi
    syscall
.unmap:
    mov eax, 11                     ; sys_munmap(map, len)
    mov rdi, [GC_MAP]
    mov rsi, [GC_MAP_LEN]
    syscall
.failed:
    mov qword [GC_MAP], 0
    mov eax, 1
    ret

; a child is marking: if it has ended, sweep with its map; if the program needs the memory, or has
; made as many new bytes as the heap had when the child forked, wait for it first; otherwise look
; again after GC_POLL more bytes
gc_poll:
    sub rsp, 16
    mov rax, [GC_ALLOCATED]
    cmp rax, [GC_THRESHOLD]
    jbe .wait                       ; no page left: the memory is needed now
    cmp rax, [GC_SNAP]
    jae .wait
    mov eax, 61                     ; sys_wait4(child, status, WNOHANG, 0)
    mov rdi, [GC_CHILD]
    mov rsi, rsp
    mov edx, 1
    xor r10d, r10d
    syscall
    test rax, rax
    jnz .ended
    mov rax, [GC_ALLOCATED]         ; still marking
    add rax, GC_POLL
    mov [GC_THRESHOLD], rax
    add rsp, 16
    ret
.wait:
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_STEPT0], rax
%endif
.wait_again:
    mov eax, 61                     ; sys_wait4(child, status, 0, 0)
    mov rdi, [GC_CHILD]
    mov rsi, rsp
    xor edx, edx
    xor r10d, r10d
    syscall
    cmp rax, -4                     ; -EINTR: again
    je .wait_again
%ifdef GC_STATS
    push rax
    call gc_now_us
    sub rax, [GC_STAT_STEPT0]
    lea rsi, [rel s_gcs_wait]
    mov edx, s_gcs_wait_len
    call gc_slow_stats
    pop rax
%endif
.ended:
    mov qword [GC_CHILD], 0
    test rax, rax
    js .lost                        ; the child could not be waited for: its map is not trusted
    cmp dword [rsp], 0
    jne .lost                       ; it did not end normally
    add rsp, 16
    jmp gc_finish
.lost:
    add rsp, 16
    call gc_unmap
    jmp gc_collect_now

; the child has marked: sweep the heap it saw with its map, in steps (the pages handed out after the
; fork stay as they are)
gc_finish:
%ifdef GC_STATS
    call gc_now_us
    mov [GC_STAT_T1], rax
%endif
    mov r13, [GC_SNAP]              ; the heap the child saw, swept with its map, in steps: the first
    mov qword [GC_MAPMODE], 2       ; one now, the others as the program allocates (rt_alloc,
    call gc_sweep_begin             ; gc_collect); the last one frees the map
    mov eax, GC_SWEEP_STEP
    call gc_sweep_step
    inc qword [GC_COUNT]
%ifdef GC_STATS
    call gc_stats
%endif
    cmp qword [GC_SWEEPING], 0
    je .swept                       ; all of it already: the threshold is set
    mov rax, [GC_ALLOCATED]
    add rax, GC_POLL
    mov [GC_THRESHOLD], rax
.swept:
    ret

gc_unmap:
    mov rdi, [GC_MAP]
    test rdi, rdi
    jz .none
    mov eax, 11                     ; sys_munmap
    mov rsi, [GC_MAP_LEN]
    syscall
    mov qword [GC_MAP], 0
.none:
    ret

%ifdef GC_STATS
; rax = µs, rsi/rdx = what: on stderr "gc <what>: X us" when X is 1 ms or more (keeps every register)
gc_slow_stats:
    cmp rax, 1000
    jb .quick
    push rax
    push rcx
    push rdx
    push rsi
    push rdi
    push r8
    push r9
    push r10
    push r11
    push rax
    mov edi, 2
    call rt_write_fd
    pop rax
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_us]
    mov edx, s_gcs_us_len
    call rt_write_fd
    pop r11
    pop r10
    pop r9
    pop r8
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rax
.quick:
    ret

; after a fork, on stderr: "gc fork: X us (the program stopped), Y MB of heap"
gc_fork_stats:
    call gc_now_us
    sub rax, [GC_STAT_STEPT0]
    push rax
    mov edi, 2
    lea rsi, [rel s_gcs_fork]
    mov edx, s_gcs_fork_len
    call rt_write_fd
    pop rax
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_forkmb]
    mov edx, s_gcs_forkmb_len
    call rt_write_fd
    mov rax, [GC_SNAP]
    shr rax, 20
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_mbheap]
    mov edx, s_gcs_mbheap_len
    jmp rt_write_fd

; after a step of the sweep: counts it and keeps the longest; after the last one, on stderr:
; "gc sweep: N steps, the longest X us"
gc_step_stats:
    call gc_now_us
    sub rax, [GC_STAT_STEPT0]
    inc qword [GC_STAT_STEPS]
    cmp rax, [GC_STAT_STEPMAX]
    jbe .kept
    mov [GC_STAT_STEPMAX], rax
.kept:
    cmp qword [GC_SWEEPING], 0
    jne .done
    mov edi, 2
    lea rsi, [rel s_gcs_steps]
    mov edx, s_gcs_steps_len
    call rt_write_fd
    mov rax, [GC_STAT_STEPS]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_longest]
    mov edx, s_gcs_longest_len
    call rt_write_fd
    mov rax, [GC_STAT_STEPMAX]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_us]
    mov edx, s_gcs_us_len
    call rt_write_fd
    mov qword [GC_STAT_STEPS], 0
    mov qword [GC_STAT_STEPMAX], 0
.done:
    ret
%endif

; on exit: a child still marking is stopped (its work is no longer needed)
gc_stop_child:
    mov rdi, [GC_CHILD]
    test rdi, rdi
    jz .none
    mov eax, 62                     ; sys_kill(child, SIGKILL)
    mov esi, 9
    syscall
.none:
    ret

%ifdef GC_STATS
; → rax = the monotonic clock in µs (keeps every other register)
gc_now_us:
    push rcx
    push rdx
    push rsi
    push rdi
    push r11
    sub rsp, 16
    mov eax, 228                    ; sys_clock_gettime(CLOCK_MONOTONIC, ts)
    mov edi, 1
    mov rsi, rsp
    syscall
    mov rax, [rsp + 8]              ; ns → µs
    xor edx, edx
    mov ecx, 1000
    div rcx
    mov rcx, [rsp]
    imul rcx, rcx, 1000000
    add rax, rcx
    add rsp, 16
    pop r11
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    ret

; after a collection, on stderr: "gc N: mark A µs, sweep B µs, live C KB, heap D KB, marked E blocks"
gc_stats:
    call gc_now_us
    mov [GC_STAT_T2], rax
    mov edi, 2
    lea rsi, [rel s_gcs_gc]
    mov edx, s_gcs_gc_len
    call rt_write_fd
    mov rax, [GC_COUNT]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_mark]
    mov edx, s_gcs_mark_len
    call rt_write_fd
    mov rax, [GC_STAT_T1]
    sub rax, [GC_STAT_T0]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_sweep]
    mov edx, s_gcs_sweep_len
    call rt_write_fd
    mov rax, [GC_STAT_T2]
    sub rax, [GC_STAT_T1]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_live]
    mov edx, s_gcs_live_len
    call rt_write_fd
    mov rax, [GC_LIVE]
    shr rax, 10
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_heap]
    mov edx, s_gcs_heap_len
    call rt_write_fd
    mov rax, [GC_BUMP]
    sub rax, [GC_HEAP_BASE]
    shr rax, 10
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_marked]
    mov edx, s_gcs_marked_len
    call rt_write_fd
    mov rax, [GC_STAT_MARKED]
    call rt_error_int
    mov edi, 2
    lea rsi, [rel s_gcs_end]
    mov edx, s_gcs_end_len
    jmp rt_write_fd
%endif

; every qword in [rsi, rdi) that points into a used block marks it and puts it
; on the mark stack (r15). r12 = descriptors, r13 = heap bytes, r14 = heap.
gc_scan:
    lea rax, [rsi + 8]
    cmp rax, rdi
    ja .done
    mov rax, [rsi]
    add rsi, 8
    sub rax, r14
    cmp rax, r13
    jae gc_scan                     ; not in the heap (most values)
    mov r8, rax
    shr r8, GC_PAGE_SHIFT
    mov r9, [r12 + r8 * 8]
    movzx ecx, r9b
    cmp ecx, PD_SMALL
    je .small
    cmp ecx, PD_LARGE
    je .large
    cmp ecx, PD_CONT
    jne gc_scan
    shr r9, 8
    sub r8, r9                      ; the first page of the block
.large:
    shl r8, GC_PAGE_SHIFT
    lea r9, [r14 + r8]
    jmp .mark
.small:
    shr r9, 8
    lea rcx, [rel gc_class_size]
    mov r9, [rcx + r9 * 8]          ; block size
    and eax, GC_PAGE - 1            ; offset in the page
    xor edx, edx
    div r9
    imul rax, r9                    ; offset of the block
    lea rcx, [rax + r9]
    cmp rcx, GC_PAGE
    ja gc_scan                      ; the unused end of the page
    shl r8, GC_PAGE_SHIFT
    add rax, r8
    lea r9, [r14 + rax]
.mark:
    mov rax, [r9]
    test al, 1
    jz gc_scan                      ; a free block
    cmp qword [GC_MAPMODE], 1
    je .mark_map
    test al, 2
    jnz gc_scan                     ; already marked
    or rax, 2
    mov [r9], rax
    jmp .push
.mark_map:                          ; a child marks in the map, not in the header (no page copied)
    mov rax, r9
    sub rax, r14
    shr rax, 5
    add rax, [GC_MAP]
    cmp byte [rax], 0
    jne gc_scan                     ; already marked
    mov byte [rax], 1
.push:
%ifdef GC_STATS
    inc qword [GC_STAT_MARKED]
%endif
    cmp r15, [GC_MSTACK_END]
    jae .overflow
    mov [r15], r9
    add r15, 8
    jmp gc_scan
.done:
    ret
.overflow:
    lea rsi, [rel s_without_memory]
    jmp rt_error

; gc_scan of a large block [rsi, rdi), skipping the 4 KiB pages that hold
; nothing (never written: zero, so they hold no references). pagemap says it
; page by page (bit 63 present, bit 62 swapped), read 1024 entries at a time
; into the mincore buffer (16 KiB at least); mincore when pagemap is not open.
gc_scan_resident:
    push rbx
    push rbp
    mov rbx, rsi
    and rbx, -4096                  ; first page
    mov rbp, rdi                    ; end
    cmp qword [GC_PAGEMAP], 0
    je .mincore
.refill:
    cmp rbx, rbp
    jae .end
    mov rdx, rbp
    sub rdx, rbx
    add rdx, 4095
    shr rdx, 12                     ; pages left
    cmp rdx, 1024
    jbe .count
    mov edx, 1024
.count:
    shl rdx, 3                      ; bytes of entries
    mov r10, rbx
    shr r10, 12 - 3                 ; the offset: page number × 8
    mov rdi, [GC_PAGEMAP]
    dec rdi
    mov rsi, [GC_MINCORE]
    mov eax, 17                     ; sys_pread64(fd, buffer, bytes, offset)
    syscall
    cmp rax, 8
    jl .whole                       ; could not read it: the rest, all of it
    shr rax, 3
    mov r10, rax                    ; entries read
    mov r11, [GC_MINCORE]
.entry:
    mov rax, [r11]
    shr rax, 62                     ; present or swapped
    jz .empty
    mov rsi, rbx
    lea rdi, [rbx + 4096]
    cmp rdi, rbp
    jbe .scan_page
    mov rdi, rbp
.scan_page:
    push r10
    push r11
    call gc_scan
    pop r11
    pop r10
.empty:
    add rbx, 4096
    add r11, 8
    cmp rbx, rbp
    jae .end
    dec r10
    jnz .entry
    jmp .refill
.whole:
    mov rsi, rbx
    mov rdi, rbp
    call gc_scan
    jmp .end
.mincore:
    mov rsi, rdi
    sub rsi, rbx
    add rsi, 4095                   ; bytes, in whole pages
    and rsi, -4096
    mov eax, 27                     ; sys_mincore(start, length, vector)
    mov rdi, rbx
    mov rdx, [GC_MINCORE]
    syscall
    test rax, rax
    jz .pages
    lea rsi, [rbx + 16]             ; mincore failed: scan it all
    mov rdi, rbp
    call gc_scan
    jmp .end
.pages:
    mov rdx, [GC_MINCORE]
.page:
    cmp rbx, rbp
    jae .end
    test byte [rdx], 1
    jz .next
    mov rsi, rbx
    lea rdi, [rbx + 4096]
    cmp rdi, rbp
    jbe .scan
    mov rdi, rbp
.scan:
    push rdx
    call gc_scan
    pop rdx
.next:
    add rbx, 4096
    inc rdx
    jmp .page
.end:
    pop rbp
    pop rbx
    ret

; frees what was not marked, clears the marks, rebuilds the free lists and the
; runs of free pages, and gives free pages back to the kernel
; The sweep, in steps. gc_sweep_begin (r13 = the heap's bytes to sweep) empties the free lists,
; which the steps fill again page by page, so no free block is ever in a list twice.
; gc_sweep_step (rax = pages at most; -1: all) sweeps the next pages and, after the last one, puts
; the free pages in runs, counts the pages handed out since the sweep began as in use, frees the
; map of a forked collection and sets the next threshold. While pages are left (GC_SWEEPING), the
; map stays and rt_alloc marks in it what it hands out, so a page swept later never frees a block
; handed out after the fork. Both keep every register.
gc_sweep_begin:
    push rax
    xor eax, eax
.clear:
    mov qword [GC_FREE + rax * 8], 0
    inc eax
    cmp eax, 21
    jb .clear
    mov qword [GC_LIVE], 0
    mov qword [GC_NDIRTY], 0
    mov qword [GC_SWEEP_POS], 0
    mov rax, r13
    shr rax, GC_PAGE_SHIFT
    mov [GC_SWEEP_END], rax
    mov qword [GC_SWEEPING], 1
    pop rax
    ret

gc_sweep_step:
    push rax
    push rbx
    push rcx
    push rdx
    push rsi
    push rdi
    push r8
    push r9
    push r10
    push r11
    push r12
    push r13
    push r14
%ifdef GC_STATS
    push rax
    call gc_now_us
    mov [GC_STAT_STEPT0], rax
    pop rax
%endif
    mov r12, [GC_DESC]
    mov r14, [GC_HEAP_BASE]
    mov r11, [GC_SWEEP_END]         ; pages to sweep in all
    mov rbx, [GC_SWEEP_POS]         ; the next one
    mov r13, r11
    cmp rax, -1
    je .page
    add rax, rbx                    ; this step stops before page rax
    cmp rax, r11
    jae .page
    mov r13, rax
.page:
    cmp rbx, r13
    jae .paused
    mov r9, [r12 + rbx * 8]
    movzx ecx, r9b
    cmp ecx, PD_SMALL
    je .small
    cmp ecx, PD_LARGE
    je .large
    cmp ecx, PD_DIRTY
    je .empty
    inc rbx
    jmp .page
.empty:                             ; an empty small page: kept, up to GC_KEEP
    mov rax, [GC_NDIRTY]
    cmp rax, GC_KEEP
    jae .give
    mov rcx, [GC_DIRTY]
    mov [rcx + rax * 8], rbx
    inc qword [GC_NDIRTY]
    mov qword [r12 + rbx * 8], PD_DIRTY
    inc rbx
    jmp .page
.give:
    mov qword [r12 + rbx * 8], 0    ; free: a pending run the program can use at once
    mov rdx, rbx
    mov r10d, 1
    call .add_run
    inc rbx
    jmp .page
.large:
    shr r9, 8                       ; its pages
    mov rax, rbx
    shl rax, GC_PAGE_SHIFT
    lea rdi, [r14 + rax]
    cmp qword [GC_MAPMODE], 2
    jne .large_header
    shr rax, 5                      ; marked in the child's map?
    add rax, [GC_MAP]
    cmp byte [rax], 0
    je .free_large
    jmp .large_kept
.large_header:
    mov rax, [rdi]
    test al, 2
    jz .free_large
    and rax, ~2
    mov [rdi], rax
.large_kept:
    mov rax, r9
    shl rax, GC_PAGE_SHIFT
    add [GC_LIVE], rax
    add rbx, r9
    jmp .page
.free_large:
    mov rdx, rbx                    ; its pages, free: a pending run the program can use at once
    mov r10, r9
.free_large_page:
    mov qword [r12 + rbx * 8], 0
    inc rbx
    dec r9
    jnz .free_large_page
    call .add_run
    jmp .page
.add_run:                           ; rdx = first page, r10 = pages: appended, pending
    mov rax, [GC_NRUNS]
    shl rax, 4
    add rax, [GC_RUNS]
    mov [rax], rdx
    mov rcx, r10
    bts rcx, RUN_PENDING
    mov [rax + 8], rcx
    inc qword [GC_NRUNS]
    ret
.small:
    mov r10, r9
    shr r10, 8                      ; class
    lea rcx, [rel gc_class_size]
    mov r9, [rcx + r10 * 8]         ; block size
    mov rdi, rbx
    shl rdi, GC_PAGE_SHIFT
    add rdi, r14                    ; the page
    lea rsi, [rdi + GC_PAGE]
    sub rsi, r9                     ; the last block that fits starts at or before this
    xor edx, edx                    ; blocks still in use
    xor r8d, r8d                    ; blocks in the page
    mov rcx, rdi
.pass1:
    cmp rcx, rsi
    ja .pass1_done
    cmp qword [GC_MAPMODE], 2
    jne .pass1_header
    mov rax, rcx                    ; marked in the child's map?
    sub rax, r14
    shr rax, 5
    add rax, [GC_MAP]
    cmp byte [rax], 0
    je .not_marked
    inc edx
    jmp .pass1_next
.pass1_header:
    mov rax, [rcx]
    test al, 2
    jz .not_marked
    and rax, ~2
    mov [rcx], rax
    inc edx
    jmp .pass1_next
.not_marked:
    mov qword [rcx], 0              ; unused (or freed now)
.pass1_next:
    inc r8
    add rcx, r9
    jmp .pass1
.pass1_done:
    test edx, edx
    jz .empty                       ; no block left
    cmp rdx, r8
    jne .keep
    add qword [GC_LIVE], GC_PAGE    ; every block in use: no free one to link, so the second pass
    inc rbx                         ; (which reads every block's header) is not needed. With the
    jmp .page                       ; child's map, a page of live blocks is not even read.
.keep:
    add qword [GC_LIVE], GC_PAGE
    mov rcx, rdi
    mov r8, [GC_FREE + r10 * 8]
.pass2:
    cmp rcx, rsi
    ja .pass2_done
    cmp qword [rcx], 0
    jne .pass2_next
    mov [rcx + 8], r8
    mov r8, rcx
.pass2_next:
    add rcx, r9
    jmp .pass2
.pass2_done:
    mov [GC_FREE + r10 * 8], r8
    inc rbx
    jmp .page
.runs:                              ; the free pages, in runs, pending: given back to the kernel in
    mov qword [GC_NRUNS], 0         ; steps (gc_give_step), or when taken (gc_get_pages)
    xor ebx, ebx
.run_find:
    cmp rbx, r11
    jae .runs_done
    cmp qword [r12 + rbx * 8], 0
    je .run_start
    inc rbx
    jmp .run_find
.run_start:
    mov r10, rbx                    ; first page of the run
.run_end:
    inc rbx
    cmp rbx, r11
    jae .run_last
    cmp qword [r12 + rbx * 8], 0
    je .run_end
    mov rdx, [GC_NRUNS]             ; (first page, pages)
    shl rdx, 4
    add rdx, [GC_RUNS]
    mov [rdx], r10
    mov rax, rbx
    sub rax, r10
    bts rax, RUN_PENDING
    mov [rdx + 8], rax
    inc qword [GC_NRUNS]
    jmp .run_find
.run_last:                          ; a run at the end of the swept pages: pending too
    mov rdx, [GC_NRUNS]
    shl rdx, 4
    add rdx, [GC_RUNS]
    mov [rdx], r10
    mov rax, rbx
    sub rax, r10
    bts rax, RUN_PENDING
    mov [rdx + 8], rax
    inc qword [GC_NRUNS]
.runs_done:
    mov qword [GC_GIVE_POS], 0      ; give them back in steps from now on
    xor eax, eax
    cmp qword [GC_NRUNS], 0
    setne al
    mov [GC_GIVING], rax
    mov rax, [GC_TAIL]
    add [GC_LIVE], rax              ; the pages handed out since the sweep began count as in use
    mov qword [GC_TAIL], 0
    mov qword [GC_SWEEPING], 0
    cmp qword [GC_MAPMODE], 2
    jne .no_map
    mov qword [GC_MAPMODE], 0
    call gc_unmap
.no_map:
    call gc_threshold
.out:
%ifdef GC_STATS
    call gc_step_stats
%endif
    pop r14
    pop r13
    pop r12
    pop r11
    pop r10
    pop r9
    pop r8
    pop rdi
    pop rsi
    pop rdx
    pop rcx
    pop rbx
    pop rax
    ret
.paused:                            ; the step's last page: done, or more to do?
    mov [GC_SWEEP_POS], rbx
    cmp rbx, r11
    jb .out
    mov rax, [GC_BUMP]              ; all swept: the pages handed out since (past the swept ones),
    sub rax, r14                    ; then the free pages in runs
    mov rdx, r11
    shl rdx, GC_PAGE_SHIFT
    sub rax, rdx
    mov [GC_TAIL], rax
    mov qword [GC_LIVE], 0          ; the bytes in use, counted again from the pages' kinds (pages
    xor ebx, ebx                    ; reused behind the sweep were not counted as it went), and the
.fresh:                             ; pages handed out ahead of it no longer marked (a collection
    cmp rbx, r11                    ; reads the kind of every page)
    jae .runs
    mov rax, [r12 + rbx * 8]
    test al, PD_FRESH
    jz .counted
    and rax, ~PD_FRESH
    mov [r12 + rbx * 8], rax
.counted:
    movzx ecx, al
    cmp ecx, PD_SMALL
    je .in_use
    cmp ecx, PD_LARGE
    je .in_use
    cmp ecx, PD_CONT
    jne .fresh_next
.in_use:
    add qword [GC_LIVE], GC_PAGE
.fresh_next:
    inc rbx
    jmp .fresh

rt_array_rep:                       ; rcx = n, rdx = value → rax = [value ; n]
    push rdx
    call rt_alloc
    pop rdx
    test rdx, rdx                   ; zero: a new heap block already comes zeroed from the kernel
    jz .ready
    mov r8, rax
    mov rdi, rax
    mov rcx, [rax - 8]
    mov rax, rdx
    rep stosq
    mov rax, r8
.ready:
    ret

; rt_error_index: rax = array/STRING, rcx = index out of bounds
rt_error_index:
    push qword [rax - 8]            ; length
    push rcx
    call rt_err_begin
    mov edi, 2
    lea rsi, [rel s_index]
    mov edx, s_index_len
    call rt_write_fd
    pop rax
    call .number
    mov edi, 2
    lea rsi, [rel s_out]
    mov edx, s_out_len
    call rt_write_fd
    pop rax
    call .number
    mov edi, 2
    lea rsi, [rel s_close_nl]
    mov edx, 2
    call rt_write_fd
    jmp rt_err_end
.number:                            ; writes rax in decimal to stderr
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    mov edi, 2
    call rt_write_fd
    add rsp, 32
    ret

; ---- bytes crus -------------------------------------------------------------
rt_write_byte:                    ; al
    mov rdx, [OUTPUT_SIZE]
    cmp rdx, OUTPUT_CAP
    jb .fits
    push rax
    call rt_flush
    pop rax
    xor edx, edx
.fits:
    mov [rdx + OUTPUT_BUF], al
    inc rdx
    mov [OUTPUT_SIZE], rdx
    ret

rt_read_byte:                         ; → rax = 0…255, or -1 at the end of input
    mov rcx, [IN_POS]
    cmp rcx, [IN_SIZE]
    jb .has
    cmp qword [IN_END], 0
    jne .finish
    call rt_flush                 ; what was already written appears before waiting
    xor eax, eax                    ; sys_read
    xor edi, edi
    mov rsi, IN_BUF
    mov edx, IN_CAP
    syscall
    test rax, rax
    jle .finished
    mov [IN_SIZE], rax
    xor ecx, ecx
.has:
    movzx eax, byte [rcx + IN_BUF]
    inc rcx
    mov [IN_POS], rcx
    ret
.finished:
    mov qword [IN_END], 1
.finish:
    mov rax, -1
    ret

; ---- strings ----------------------------------------------------------------
rt_str_equal:                       ; rax, rcx → rax = 1 if the contents are equal
    cmp rax, rcx
    je .equal                       ; the same text
    mov rdx, [rax - 8]
    cmp rdx, [rcx - 8]
    jne .different
    mov rsi, rax
    mov rdi, rcx
.words:                             ; 8 bytes at a time (a text's block has room for whole words
    cmp rdx, 8                      ; only up to its length: the rest goes a byte at a time)
    jb .bytes
    mov rcx, [rsi]
    cmp rcx, [rdi]
    jne .different
    add rsi, 8
    add rdi, 8
    sub rdx, 8
    jmp .words
.bytes:
    test rdx, rdx
    jz .equal
    mov cl, [rsi]
    cmp cl, [rdi]
    jne .different
    inc rsi
    inc rdi
    dec rdx
    jmp .bytes
.equal:
    mov eax, 1
    ret
.different:
    xor eax, eax
    ret

; ---- error output (!>>): unbuffered, after flushing normal output -----
rt_error_int:
    push rax
    call rt_flush
    pop rax
    sub rsp, 32
    lea rdi, [rsp + 32]
    call rt_decimal
    lea rdx, [rsp + 32]
    sub rdx, rsi
    mov edi, 2
    call rt_write_fd
    add rsp, 32
    ret

rt_error_bool:
    push rax
    call rt_flush
    pop rax
    test rax, rax
    jz .falso_
    lea rsi, [rel s_true]
    mov edx, 4
    jmp .write
.falso_:
    lea rsi, [rel s_false]
    mov edx, 5
.write:
    mov edi, 2
    jmp rt_write_fd

rt_error_str:
    push rax
    call rt_flush
    pop rax
    mov rsi, rax
    mov rdx, [rax - 8]
    mov edi, 2
    jmp rt_write_fd

; ---- arquivos -----------------------------------------------------------------
; rt_read_file: rax = path (STRING) → rax = contents (STRING, with a 0 at the end)
rt_read_file_opt:
    push qword 1                    ; failure → returns 0
    jmp rt_read_file.body
rt_read_file:
    push qword 0                    ; failure → runtime error
.body:
    push rbx
    push r12
    push r13
    sub rsp, 4096                   ; 0-terminated path
    mov byte [rsp], 0
    mov rcx, [rax - 8]
    cmp rcx, 4095
    ja .fail_long
    mov rsi, rax
    mov rdi, rsp
    rep movsb
    mov byte [rdi], 0
    mov rcx, [rax - 8]              ; a zero byte inside the path: the kernel would open
    test rcx, rcx                   ; another file (the path cut at the zero)
    jz .path_ok
    push rax
    mov rdi, rax
    xor eax, eax
    repne scasb
    pop rax
    je .fail
.path_ok:
    mov eax, 257                    ; sys_openat
    mov rdi, -100                   ; AT_FDCWD
    mov rsi, rsp
    xor edx, edx                    ; O_RDONLY
    syscall
    test rax, rax
    js .fail
    mov r12, rax                    ; fd
    mov eax, 8                      ; sys_lseek(fd, 0, SEEK_END) = size
    mov rdi, r12
    xor esi, esi
    mov edx, 2
    syscall
    test rax, rax
    jle .stream                     ; no size (a pipe, /proc, /dev/stdin): read to the end
    mov r13, rax                    ; length
    mov eax, 8                      ; back to the start
    mov rdi, r12
    xor esi, esi
    xor edx, edx
    syscall
    lea rcx, [r13 + 8]              ; 8-byte elements for size + 1 bytes
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13              ; size in bytes
    push rax
    mov rbx, rax
.read:
    test r13, r13
    jz .got
    xor eax, eax                    ; sys_read
    mov rdi, r12
    mov rsi, rbx
    mov rdx, r13
    syscall
    test rax, rax
    js .fail_reading
    jz .shrank
    add rbx, rax
    sub r13, rax
    jmp .read
.stream:                          ; unknown size: a buffer that doubles until read gives 0
    mov r13d, 65536                 ; capacity
    lea rcx, [r13 + 8]
    shr rcx, 3
    call rt_alloc
    push rax                        ; [rsp] = the buffer (a GC root on the stack)
    xor ebx, ebx                    ; bytes read so far
.stream_read:
    cmp rbx, r13
    jb .stream_room
    lea rcx, [r13 * 2 + 8]          ; full: a buffer twice as big, with what was read
    shr rcx, 3
    call rt_alloc
    mov rdi, rax
    mov rsi, [rsp]
    mov rcx, rbx
    rep movsb
    mov [rsp], rax
    shl r13, 1
.stream_room:
    mov rsi, [rsp]
    add rsi, rbx
    mov rdx, r13
    sub rdx, rbx
    xor eax, eax                    ; sys_read
    mov rdi, r12
    syscall
    cmp rax, -4                     ; -EINTR: again
    je .stream_read
    test rax, rax
    js .fail_reading
    jz .stream_end
    add rbx, rax
    jmp .stream_read
.stream_end:
    mov rax, [rsp]
    mov [rax - 8], rbx              ; the length (the block keeps its size)
    add rbx, rax                    ; where the 0 goes
    jmp .got
.shrank:                          ; the file shrank while being read
    mov rax, [rsp]
    sub [rax - 8], r13
.got:
    mov byte [rbx], 0
    mov eax, 3                      ; sys_close
    mov rdi, r12
    syscall
    pop rax
.back:
    add rsp, 4096
    pop r13
    pop r12
    pop rbx
    add rsp, 8                      ; flag
    ret
.fail_reading:
    pop rax
.fail:
.fail_long:
    cmp qword [rsp + 4096 + 24], 0
    je .fatal
    xor eax, eax                    ; optional: "_"
    jmp .back
.fatal:
    call rt_err_begin
    mov edi, 2
    lea rsi, [rel s_read]
    mov edx, s_read_len
    call rt_write_fd
    mov rsi, rsp                    ; path (cut if it is too long)
    xor edx, edx
.size_path:
    cmp edx, 4095
    jae .write_path
    cmp byte [rsi + rdx], 0
    je .write_path
    inc edx
    jmp .size_path
.write_path:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_quote_nl]
    mov edx, 2
    call rt_write_fd
    jmp rt_err_end

; rt_text: rax = ARRAY of INT → rax = STRING with the low byte of each element
rt_text:
    push rbx
    push r12
    mov rbx, rax
    mov r12, [rax - 8]              ; n
    lea rcx, [r12 + 8]
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r12
    xor ecx, ecx
.copy:
    cmp rcx, r12
    jae .finish
    mov dl, [rbx + rcx * 8]
    mov [rax + rcx], dl
    inc rcx
    jmp .copy
.finish:
    mov byte [rax + r12], 0
    pop r12
    pop rbx
    ret

; ---- optionals: rax = value, rdx = presence ---------------------------------
rt_print_int_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_int
rt_print_bool_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_bool
rt_print_str_opt:
    test rdx, rdx
    jz rt_print_absent
    jmp rt_print_str
rt_print_absent:
    lea rsi, [rel s_absent]
    mov edx, 1
    jmp rt_buffer

rt_error_int_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_int
rt_error_bool_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_bool
rt_error_str_opt:
    test rdx, rdx
    jz rt_error_absent
    jmp rt_error_str
rt_error_absent:
    call rt_flush
    lea rsi, [rel s_absent]
    mov edx, 1
    mov edi, 2
    jmp rt_write_fd

; rt_sleep: rax = milliseconds (≤ 0: returns at once). Flushes the output first,
; so what was written shows up before the wait. Restarts after a signal.
rt_sleep:
    test rax, rax
    jle .done
    push rax
    call rt_flush
    pop rax
    sub rsp, 16                     ; struct timespec { seconds, nanoseconds }
    xor edx, edx
    mov ecx, 1000
    div rcx
    mov [rsp], rax
    imul rdx, rdx, 1000000
    mov [rsp + 8], rdx
.again:
    mov eax, 35                     ; sys_nanosleep(req, rem): rem = req,
    mov rdi, rsp                    ; so an interrupted sleep resumes with
    mov rsi, rsp                    ; the time that was left
    syscall
    cmp rax, -4                     ; -EINTR
    je .again
    add rsp, 16
.done:
    ret

; rt_write_file: rax = path, rcx = text (STRINGs). Creates or replaces the file
; atomically: writes "<path>.nihil-tmp", fsyncs it and renames it over the path,
; so a crash leaves either the old file or the new one, never half of it.
; rt_append_file: same arguments; appends the text (creating the file), then fsyncs.
; rt_write_at: same arguments and rdx = offset; writes the text there (pwrite,
; creating the file, keeping the rest of it), then fsyncs.
; rt_write_at_ns: the same without the fsync (the caller syncs later).
; rt_truncate: rax = path, rdx = size: cuts the file to that size, then fsyncs.
; rt_truncate_ns: the same without the fsync.
; Any failure is a runtime error naming the file and the reason (exit code 2).
%define WF_PATH     0               ; [rsp + WF_PATH]: the path, 0-terminated
%define WF_TEMP     4096            ; [rsp + WF_TEMP]: the temporary path
%define WF_FRAME    8192
%define WF_FLAG     (WF_FRAME + 40) ; 0 replace, 1 append, 2 at an offset, 3 truncate, 4 at an offset without fsync, 5 truncate without fsync
%define WF_OFFSET   (WF_FRAME + 48) ; where the next byte goes (flag 2)
%define WF_MAX_PATH 4080            ; leaves room for ".nihil-tmp" and the 0
rt_write_at:
    push rdx
    push qword 2
    jmp rt_write_file.body
rt_write_at_ns:
    push rdx
    push qword 4
    jmp rt_write_file.body
rt_truncate:
    mov rcx, rax                    ; any STRING: no text is written
    push rdx
    push qword 3
    jmp rt_write_file.body
rt_truncate_ns:
    mov rcx, rax
    push rdx
    push qword 5
    jmp rt_write_file.body
rt_append_file:
    push qword 0
    push qword 1
    jmp rt_write_file.body
rt_write_file:
    push qword 0
    push qword 0
.body:
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, WF_FRAME
    mov r12, rcx                    ; the text
    mov rbx, [rax - 8]              ; length of the path
    mov rcx, rbx
    cmp rcx, WF_MAX_PATH
    jbe .copy
    mov ecx, WF_MAX_PATH            ; copied cut, only for the message
.copy:
    mov rsi, rax
    lea rdi, [rsp + WF_PATH]
    rep movsb
    mov byte [rdi], 0
    mov rcx, rbx                    ; a zero byte inside the path (what was copied of it)
    cmp rcx, WF_MAX_PATH
    jbe .scan
    mov ecx, WF_MAX_PATH
.scan:
    test rcx, rcx
    jz .no_zero
    lea rdi, [rsp + WF_PATH]
    xor eax, eax
    repne scasb
    jne .no_zero
    mov rax, -255                   ; not an errno: "the path has a zero byte"
    jmp .report
.no_zero:
    mov rax, -36                    ; ENAMETOOLONG
    cmp rbx, WF_MAX_PATH
    ja .report
    cmp qword [rsp + WF_FLAG], 0
    jne .append
    lea rdi, [rsp + WF_TEMP]        ; temporary = path + ".nihil-tmp"
    lea rsi, [rsp + WF_PATH]
    mov rcx, rbx
    rep movsb
    lea rsi, [rel s_tmp_suffix]
    mov ecx, s_tmp_suffix_len
    rep movsb
    lea r15, [rsp + WF_TEMP]
    mov edx, 0x241                  ; O_WRONLY | O_CREAT | O_TRUNC
    jmp .open
.append:
    lea r15, [rsp + WF_PATH]
    mov edx, 0x441                  ; O_WRONLY | O_CREAT | O_APPEND
    cmp qword [rsp + WF_FLAG], 1
    je .open
    mov edx, 0x41                   ; O_WRONLY | O_CREAT (flags 2 and 4: in place)
    cmp qword [rsp + WF_FLAG], 3
    je .must_exist
    cmp qword [rsp + WF_FLAG], 5
    jne .open
.must_exist:
    mov edx, 1                      ; O_WRONLY (flags 3 and 5: it must exist)
.open:
    mov eax, 257                    ; sys_openat(AT_FDCWD, r15, flags, 0644)
    mov rdi, -100
    mov rsi, r15
    mov r10d, 420
    syscall
    test rax, rax
    js .report
    mov r13, rax                    ; fd
    cmp qword [rsp + WF_FLAG], 3
    je .truncate
    cmp qword [rsp + WF_FLAG], 5
    jne .text
.truncate:
    mov eax, 77                     ; sys_ftruncate(fd, size)
    mov rdi, r13
    mov rsi, [rsp + WF_OFFSET]
    syscall
    test rax, rax
    js .fail_open_fd
    jmp .sync
.text:
    mov rbx, r12                    ; next byte to write
    mov r14, [r12 - 8]              ; bytes left
.write:
    test r14, r14
    jz .sync
    mov eax, 1                      ; sys_write
    mov rdi, r13
    mov rsi, rbx
    mov rdx, r14
    cmp qword [rsp + WF_FLAG], 2
    jb .syscall_write
    mov eax, 18                     ; sys_pwrite64(fd, buf, count, offset)
    mov r10, [rsp + WF_OFFSET]
.syscall_write:
    syscall
    cmp rax, -4                     ; -EINTR: try again
    je .write
    test rax, rax
    js .fail_open_fd
    add [rsp + WF_OFFSET], rax
    add rbx, rax
    sub r14, rax
    jmp .write
.sync:
    cmp qword [rsp + WF_FLAG], 4
    jae .close                      ; flags 4 and 5: no fsync
    mov eax, 74                     ; sys_fsync: the data is on the disk
    mov rdi, r13
    syscall
    test rax, rax
    js .fail_open_fd
.close:
    mov eax, 3                      ; sys_close
    mov rdi, r13
    syscall
    test rax, rax
    js .fail_closed
    cmp qword [rsp + WF_FLAG], 0
    jne .done
    mov eax, 82                     ; sys_rename(temporary, path)
    lea rdi, [rsp + WF_TEMP]
    lea rsi, [rsp + WF_PATH]
    syscall
    test rax, rax
    js .fail_closed
.done:
    add rsp, WF_FRAME
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    add rsp, 16                     ; flag and offset
    ret
.fail_open_fd:
    mov r14, rax
    mov eax, 3                      ; close it anyway
    mov rdi, r13
    syscall
    mov rax, r14
.fail_closed:
    cmp qword [rsp + WF_FLAG], 0
    jne .report
    mov r14, rax
    mov eax, 87                     ; sys_unlink(temporary): leave no debris
    lea rdi, [rsp + WF_TEMP]
    syscall
    mov rax, r14
.report:                            ; rax = -errno
    neg rax
    mov r14, rax
    call rt_err_begin
    mov edi, 2
    lea rsi, [rel s_write]
    mov edx, s_write_len
    call rt_write_fd
    lea rsi, [rsp + WF_PATH]
    xor edx, edx
.size_path:
    cmp byte [rsi + rdx], 0
    je .write_path
    inc edx
    jmp .size_path
.write_path:
    mov edi, 2
    call rt_write_fd
    mov edi, 2
    lea rsi, [rel s_quote_colon]
    mov edx, 3
    call rt_write_fd
    lea rbx, [rel errno_reasons]    ; [errno byte][length byte][text] …, 0 at the end
.find:
    movzx eax, byte [rbx]
    test eax, eax
    jz .unknown
    movzx edx, byte [rbx + 1]
    cmp rax, r14
    je .reason
    lea rbx, [rbx + rdx + 2]
    jmp .find
.reason:
    mov edi, 2
    lea rsi, [rbx + 2]
    call rt_write_fd
    jmp .end
.unknown:
    mov edi, 2
    lea rsi, [rel s_errno]
    mov edx, s_errno_len
    call rt_write_fd
    mov rax, r14
    call rt_error_int               ; the number, on stderr
.end:
    mov edi, 2
    lea rsi, [rel s_nl]
    mov edx, 1
    call rt_write_fd
    jmp rt_err_end

; rt_read_at: rax = path (STRING), rcx = offset, rdx = bytes wanted.
; → rax = a new STRING with the bytes at that offset (fewer at the end of the
;   file, none if the offset is negative or past the end), or 0 if the file
;   does not open; rdx = the file's size (-1 if it does not open).
; rcx = the file's stamp: its st_mtime in nanoseconds mixed with its inode, so it
;   changes when the file is written or replaced (0 if it does not open).
; Reads only those bytes (pread), whatever the size of the file.
; The file is kept open for the next call (FD_CACHE, 4 files, paths up to 256 bytes): each call
; asks the kernel for what is at the path now (newfstatat), and uses the open file only while it
; is the same one (st_dev and st_ino); a file replaced (a rename, an editor) or removed is opened
; again or forgotten, so a call sees what another program wrote, as when it opened every time.
; Frame: the path at rsp (4096), then at rsp + 4096 the stat buffer (144 bytes), the stamp (+160),
; whether the fd is kept (+168) and the path's length (+176).
rt_read_at:
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 4096 + 256
    mov r12, rcx                    ; offset
    mov r13, rdx                    ; bytes wanted
    mov rcx, [rax - 8]
    cmp rcx, 4095
    ja .no_file
    mov [rsp + 4096 + 176], rcx     ; the path's length
    mov rsi, rax
    mov rdi, rsp
    rep movsb
    mov byte [rdi], 0
    mov rcx, [rax - 8]              ; a zero byte inside the path: no such file
    test rcx, rcx
    jz .path_ok
    push rax
    mov rdi, rax
    xor eax, eax
    repne scasb
    pop rax
    je .no_file
.path_ok:
    mov qword [rsp + 4096 + 168], 0 ; the fd is closed at the end, unless it is kept
    mov eax, 262                    ; sys_newfstatat(AT_FDCWD, path, stat, 0): what is there now
    mov rdi, -100
    mov rsi, rsp
    lea rdx, [rsp + 4096]
    xor r10d, r10d
    syscall
    mov r14, rax
    xor ebx, ebx                    ; the slot that keeps this path open, if any
    mov r8, FD_CACHE
    mov r9d, FD_SLOTS
.find:
    cmp qword [r8], 0
    je .find_next
    mov rcx, [rsp + 4096 + 176]
    cmp rcx, [r8 + 24]
    jne .find_next
    mov rsi, rsp
    lea rdi, [r8 + 32]
    repe cmpsb
    jne .find_next
    mov rbx, r8
    jmp .found
.find_next:
    add r8, FD_SLOT
    dec r9d
    jnz .find
.found:
    test r14, r14
    js .gone
    test rbx, rbx
    jz .open
    mov rax, [rsp + 4096]           ; the same file as the one kept open?
    cmp rax, [rbx + 8]
    jne .stale
    mov rax, [rsp + 4096 + 8]
    cmp rax, [rbx + 16]
    jne .stale
    mov r14, [rbx]                  ; yes: its fd, and the stat just made
    dec r14
    mov qword [rsp + 4096 + 168], 1
    jmp .have_stat
.gone:                              ; nothing at the path: forget a file kept for it
    test rbx, rbx
    jz .no_file
    mov eax, 3                      ; sys_close
    mov rdi, [rbx]
    dec rdi
    syscall
    mov qword [rbx], 0
    jmp .no_file
.stale:                             ; another file at the path now: close the old one
    mov eax, 3
    mov rdi, [rbx]
    dec rdi
    syscall
    mov qword [rbx], 0
.open:
    mov eax, 257                    ; sys_openat(AT_FDCWD, path, O_RDONLY | O_CLOEXEC)
    mov rdi, -100
    mov rsi, rsp
    mov edx, 0x80000
    syscall
    test rax, rax
    js .no_file
    mov r14, rax                    ; fd
    mov eax, 5                      ; sys_fstat(fd, buffer): the file that was opened
    mov rdi, r14
    lea rsi, [rsp + 4096]
    syscall
    test rax, rax
    js .close_no_file
    mov rcx, [rsp + 4096 + 176]     ; kept open, in the next slot, if the path fits
    cmp rcx, 256
    ja .have_stat
    mov r8, FD_CACHE_NEXT
    mov rax, [r8]
    lea r9, [rax + 1]
    and r9, FD_SLOTS - 1
    mov [r8], r9
    imul rax, rax, FD_SLOT
    mov r8, FD_CACHE
    add r8, rax
    cmp qword [r8], 0
    je .keep
    mov eax, 3                      ; the slot's previous file is closed
    mov rdi, [r8]
    dec rdi
    syscall
.keep:
    lea rax, [r14 + 1]
    mov [r8], rax
    mov rax, [rsp + 4096]           ; st_dev
    mov [r8 + 8], rax
    mov rax, [rsp + 4096 + 8]       ; st_ino
    mov [r8 + 16], rax
    mov rcx, [rsp + 4096 + 176]
    mov [r8 + 24], rcx
    mov rsi, rsp
    lea rdi, [r8 + 32]
    rep movsb
    mov qword [rsp + 4096 + 168], 1
.have_stat:
    mov r15, [rsp + 4096 + 48]      ; st_size
    imul rax, [rsp + 4096 + 88], 1000000000 ; the stamp: st_mtime in nanoseconds …
    add rax, [rsp + 4096 + 96]
    mov rdx, 0x9E3779B97F4A7C15     ; … mixed with st_ino (a rename gives a new file)
    imul rdx, [rsp + 4096 + 8]
    add rax, rdx
    mov [rsp + 4096 + 160], rax     ; kept for the return
    xor ecx, ecx                    ; bytes to read: 0 outside the file …
    test r12, r12
    js .count
    cmp r12, r15
    jge .count
    mov rcx, r15                    ; … otherwise min(wanted, size - offset)
    sub rcx, r12
    test r13, r13
    js .count_zero
    cmp rcx, r13
    jbe .count
    mov rcx, r13
    jmp .count
.count_zero:
    xor ecx, ecx
.count:
    mov r13, rcx                    ; bytes to read
    add rcx, 8                      ; 8-byte elements for r13 + 1 bytes
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13
    mov rbx, rax
    xor ecx, ecx                    ; read so far
.read:
    cmp rcx, r13
    jae .got
    push rcx
    mov eax, 17                     ; sys_pread64(fd, buf, count, offset)
    mov rdi, r14
    lea rsi, [rbx + rcx]
    mov rdx, r13
    sub rdx, rcx
    lea r10, [r12 + rcx]
    syscall
    pop rcx
    cmp rax, -4                     ; -EINTR: again
    je .read
    test rax, rax
    jle .shrank                     ; error or end: keep what was read
    add rcx, rax
    jmp .read
.shrank:
    mov [rbx - 8], rcx
.got:
    mov rcx, [rbx - 8]
    mov byte [rbx + rcx], 0
    cmp qword [rsp + 4096 + 168], 0
    jne .kept
    mov eax, 3                      ; sys_close
    mov rdi, r14
    syscall
.kept:
    mov rax, rbx
    mov rdx, r15
    mov rcx, [rsp + 4096 + 160]
    jmp .back
.close_no_file:
    mov eax, 3
    mov rdi, r14
    syscall
.no_file:
    xor eax, eax
    mov rdx, -1
    xor ecx, ecx
.back:
    add rsp, 4096 + 256
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    ret

; rt_concat: rax = a, rcx = b → rax = new STRING with a followed by b
rt_concat:
    push rbx
    push r12
    push r13
    mov rbx, rax
    mov r12, rcx
    mov r13, [rbx - 8]
    add r13, [r12 - 8]              ; total size
    lea rcx, [r13 + 8]
    shr rcx, 3
    call rt_alloc
    mov [rax - 8], r13
    mov rdi, rax
    mov rsi, rbx
    mov rcx, [rbx - 8]
    rep movsb
    mov rsi, r12
    mov rcx, [r12 - 8]
    rep movsb
    mov byte [rdi], 0
    pop r13
    pop r12
    pop rbx
    ret

; ---- data ------------------------------------------------------------------
align 8
pow10_table:                        ; 10^0 … 10^22: every one exact as a double (Clinger's fast path)
    dq 1.0e0, 1.0e1, 1.0e2, 1.0e3, 1.0e4, 1.0e5, 1.0e6, 1.0e7, 1.0e8, 1.0e9, 1.0e10, 1.0e11
    dq 1.0e12, 1.0e13, 1.0e14, 1.0e15, 1.0e16, 1.0e17, 1.0e18, 1.0e19, 1.0e20, 1.0e21, 1.0e22
s_true:     db "true"
s_absent:  db "_"
s_false:    db "false"
s_maps:       db "/proc/self/maps", 0
s_pagemap:    db "/proc/self/pagemap", 0
s_nihil:      db "nihil: "
s_nihil_len   equ $ - s_nihil
s_nl:       db 10
s_div_zero: db "division by zero", 0
s_size_negativo: db "negative array size", 0
s_size_large:   db "array too large", 0
s_without_memory:  db "out of memory", 0
s_too_deep:   db "more than 64 protected calls inside each other", 0
s_index:   db "index "
s_index_len equ $ - s_index
s_out:     db " out of bounds (size "
s_out_len  equ $ - s_out
s_close_nl: db ")", 10
