%macro REASON 2
    db %1, %%e - %%s
%%s: db %2
%%e:
%endmacro
errno_reasons:
    REASON 2,   "no such file or directory"
    REASON 13,  "permission denied"
    REASON 17,  "file exists"
    REASON 20,  "a part of the path is not a directory"
    REASON 21,  "it is a directory"
    REASON 28,  "no space left on the device"
    REASON 30,  "read-only file system"
    REASON 36,  "the path is too long"
    REASON 122, "disk quota exceeded"
    REASON 255, "the path has a zero byte"
    db 0

; ---- checking the table offsets (assembly fails if they differ) -----
%macro ASSERT_AT 2
    times -(((%1) - start) != (%2)) db 0
%endmacro
